def validate_square(matrix):
    n = len(matrix)
    for i in range(n):
        if len(matrix[i]) != n:
            raise ValueError("row %d has length %d, expected %d" % (i, len(matrix[i]), n))
    return n


def transpose_in_place(matrix):
    n = validate_square(matrix)
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    return matrix


def reverse_sublists(matrix):
    for i in range(len(matrix)):
        row = matrix[i]
        n = len(row)
        for j in range(n // 2):
            row[j], row[n - 1 - j] = row[n - 1 - j], row[j]
    return matrix


def rotate_90(matrix):
    transpose_in_place(matrix)
    reverse_sublists(matrix)
    return matrix


def build_matrix(n):
    matrix = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(i * n + j + 1)
        matrix.append(row)
    return matrix


def format_matrix(matrix):
    width = 1
    for row in matrix:
        for value in row:
            if len(str(value)) > width:
                width = len(str(value))
    lines = []
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append(str(matrix[i][j]).rjust(width))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def main():
    matrix = build_matrix(4)
    print("before:")
    print(format_matrix(matrix))
    rotate_90(matrix)
    print("after:")
    print(format_matrix(matrix))
    return matrix


if __name__ == "__main__":
    main()

