def check_block(board, start_row_index, start_col_index):
    seen = set()
    for i in range(start_row_index, start_row_index + 3):
        for j in range(start_col_index, start_col_index + 3):
            value = board[i][j]
            if value == 0:
                continue
            if value in seen:
                return False
            seen.add(value)
    return True


def check_rows(board):
    for i in range(9):
        seen = set()
        for j in range(9):
            value = board[i][j]
            if value == 0:
                continue
            if value in seen:
                return False
            seen.add(value)
    return True


def check_columns(board):
    for j in range(9):
        seen = set()
        for i in range(9):
            value = board[i][j]
            if value == 0:
                continue
            if value in seen:
                return False
            seen.add(value)
    return True


def validate_shape(board):
    if len(board) != 9:
        raise ValueError("board must have exactly 9 rows")
    for i, row in enumerate(board):
        if len(row) != 9:
            raise ValueError("row %d must have exactly 9 cells" % i)
        for j, value in enumerate(row):
            if not isinstance(value, int) or isinstance(value, bool):
                raise ValueError("cell (%d, %d) must be an integer" % (i, j))
            if not 0 <= value <= 9:
                raise ValueError("cell (%d, %d) must be between 0 and 9" % (i, j))


def is_valid_sudoku(board):
    validate_shape(board)
    if not check_rows(board) or not check_columns(board):
        return False
    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            if not check_block(board, i, j):
                return False
    return True


def format_board(board):
    lines = []
    for i in range(9):
        cells = []
        for j in range(9):
            value = board[i][j]
            cells.append(str(value) if value else ".")
            if j % 3 == 2 and j != 8:
                cells.append("|")
        lines.append(" ".join(cells))
        if i % 3 == 2 and i != 8:
            lines.append("-" * len(lines[-1]))
    return "\n".join(lines)


def main():
    board = [
        [5, 3, 0, 0, 7, 0, 0, 0, 0],
        [6, 0, 0, 1, 9, 5, 0, 0, 0],
        [0, 9, 8, 0, 0, 0, 0, 6, 0],
        [8, 0, 0, 0, 6, 0, 0, 0, 3],
        [4, 0, 0, 8, 0, 3, 0, 0, 1],
        [7, 0, 0, 0, 2, 0, 0, 0, 6],
        [0, 6, 0, 0, 0, 0, 2, 8, 0],
        [0, 0, 0, 4, 1, 9, 0, 0, 5],
        [0, 0, 0, 0, 8, 0, 0, 7, 9],
    ]
    print(format_board(board))
    result = is_valid_sudoku(board)
    print("valid:", result)
    return result


if __name__ == "__main__":
    main()

