def describe_edits(word1, word2, matrix):
    """Walk the matrix backwards and name the edits along an optimal path."""
    steps = []
    index, column = len(word1), len(word2)
    while index > 0 or column > 0:
        if index > 0 and column > 0 and matrix[index][column] == matrix[index - 1][column - 1] and word1[index - 1] == word2[column - 1]:
            steps.append("keep {}".format(word1[index - 1]))
            index, column = index - 1, column - 1
        elif index > 0 and column > 0 and matrix[index][column] == matrix[index - 1][column - 1] + 1:
            steps.append("replace {} with {}".format(word1[index - 1], word2[column - 1]))
            index, column = index - 1, column - 1
        elif index > 0 and matrix[index][column] == matrix[index - 1][column] + 1:
            steps.append("delete {}".format(word1[index - 1]))
            index -= 1
        else:
            steps.append("insert {}".format(word2[column - 1]))
            column -= 1
    steps.reverse()
    return steps


def main():
    word1, word2 = "kitten", "sitting"
    distance, matrix = compute_edit_distance(word1, word2)
    lines = print_dp_matrix(matrix)

    print("{} -> {}: distance {}".format(word1, word2, distance))
    for line in lines:
        print(line)
    for key, step in enumerate(describe_edits(word1, word2, matrix), start=1):
        print("{:>2}. {}".format(key, step))

    return {"distance": distance, "matrix": lines}


if __name__ == "__main__":
    main()

