def check_rows(board):
    n = len(board)
    for i in range(n):
        first = board[i][0]
        if first == ' ':
            continue
        for j in range(1, n):
            if board[i][j] != first:
                break
        else:
            return first
    return None


def check_cols(board):
    n = len(board)
    for j in range(n):
        first = board[0][j]
        if first == ' ':
            continue
        for i in range(1, n):
            if board[i][j] != first:
                break
        else:
            return first
    return None


def check_diagonals(board):
    n = len(board)
    first = board[0][0]
    if first != ' ':
        for k in range(1, n):
            if board[k][k] != first:
                break
        else:
            return first
    first = board[0][n - 1]
    if first != ' ':
        for k in range(1, n):
            if board[k][n - 1 - k] != first:
                break
        else:
            return first
    return None


def validate_board(board):
    n = len(board)
    if n == 0:
        raise ValueError("board must not be empty")
    for i in range(n):
        if len(board[i]) != n:
            raise ValueError("row %d is not of length %d" % (i, n))
        for j in range(n):
            if board[i][j] not in ('X', 'O', ' '):
                raise ValueError("bad symbol %r at (%d, %d)" % (board[i][j], i, j))


def board_is_full(board):
    n = len(board)
    for i in range(n):
        for j in range(n):
            if board[i][j] == ' ':
                return False
    return True


def evaluate_board(board):
    validate_board(board)
    for check in (check_rows, check_cols, check_diagonals):
        winner = check(board)
        if winner is not None:
            return winner
    if board_is_full(board):
        return 'Draw'
    return 'Ongoing'


def format_board(board):
    lines = []
    for i in range(len(board)):
        lines.append(' | '.join(board[i]))
    return '\n'.join(lines)


def main():
    size = 4
    board = [[' '] * size for _ in range(size)]
    for k in range(size):
        board[k][k] = 'X'
    for i in range(size - 1):
        board[i][i + 1] = 'O'
    print(format_board(board))
    result = evaluate_board(board)
    print('Result:', result)
    return result


if __name__ == '__main__':
    main()

