def validate_matrix(matrix):
    if not matrix:
        raise ValueError("matrix must have at least one row")
    width = len(matrix[0])
    for i in range(len(matrix)):
        if len(matrix[i]) != width:
            raise ValueError("row %d has length %d, expected %d" % (i, len(matrix[i]), width))
    return width


def dense_to_csr(matrix):
    width = validate_matrix(matrix)
    values = []
    col_indices = []
    row_pointers = [0]
    for i in range(len(matrix)):
        for j in range(width):
            if matrix[i][j] != 0:
                values.append(matrix[i][j])
                col_indices.append(j)
        row_pointers.append(len(values))
    return values, col_indices, row_pointers


def csr_to_dense(values, col_indices, row_pointers, width):
    height = len(row_pointers) - 1
    matrix = []
    for i in range(height):
        row = [0] * width
        for k in range(row_pointers[i], row_pointers[i + 1]):
            row[col_indices[k]] = values[k]
        matrix.append(row)
    return matrix


def csr_row_sums(values, row_pointers):
    sums = []
    for i in range(len(row_pointers) - 1):
        total = 0
        for k in range(row_pointers[i], row_pointers[i + 1]):
            total += values[k]
        sums.append(total)
    return sums


def empty_row_indices(row_pointers):
    empty = []
    for i in range(len(row_pointers) - 1):
        if row_pointers[i] == row_pointers[i + 1]:
            empty.append(i)
    return empty


def format_matrix(matrix):
    pad = 1
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            pad = max(pad, len(str(matrix[i][j])))
    lines = []
    for i in range(len(matrix)):
        parts = []
        for j in range(len(matrix[i])):
            parts.append(str(matrix[i][j]).rjust(pad))
        lines.append(" ".join(parts))
    return "\n".join(lines)


def matrices_equal(a, b):
    if len(a) != len(b):
        return False
    for i in range(len(a)):
        if len(a[i]) != len(b[i]):
            return False
        for j in range(len(a[i])):
            if a[i][j] != b[i][j]:
                return False
    return True


def main():
    dense = [
        [0, 0, 3, 0],
        [22, 0, 0, 0],
        [0, 0, 0, 0],
        [0, 7, 0, 5],
    ]
    values, col_indices, row_pointers = dense_to_csr(dense)
    width = len(dense[0])
    rebuilt = csr_to_dense(values, col_indices, row_pointers, width)

    print("values:       %s" % values)
    print("col_indices:  %s" % col_indices)
    print("row_pointers: %s" % row_pointers)
    print("row sums:     %s" % csr_row_sums(values, row_pointers))
    print("empty rows:   %s" % empty_row_indices(row_pointers))
    print("reconstructed:")
    print(format_matrix(rebuilt))
    print("round trip exact: %s" % matrices_equal(dense, rebuilt))

    return (values, col_indices, row_pointers), rebuilt


if __name__ == "__main__":
    main()

