        for key in range(row_pointers[index], row_pointers[index + 1]):
            total += values[key]
        sums.append(total)
    return sums


def empty_row_indices(row_pointers):
    empty = []
    for index in range(len(row_pointers) - 1):
        if row_pointers[index] == row_pointers[index + 1]:
            empty.append(index)
    return empty


def format_matrix(matrix):
    pad = 1
    for index in range(len(matrix)):
        for column in range(len(matrix[index])):
            pad = max(pad, len(str(matrix[index][column])))
    lines = []
    for index in range(len(matrix)):
        parts = []
        for column in range(len(matrix[index])):
            parts.append(str(matrix[index][column]).rjust(pad))
        lines.append(" ".join(parts))
    return "\n".join(lines)


def matrices_equal(a, b):
    if len(a) != len(b):
        return False
    for index in range(len(a)):
        if len(a[index]) != len(b[index]):
            return False
        for column in range(len(a[index])):
            if a[index][column] != b[index][column]:
                return False
    return True


def main():
    dense = [
        [0, 0, 3, 0],
        [22, 0, 0, 0],
        [0, 0, 0, 0],
        [0, 7, 0, 5],
    ]
    values, col_indices, row_pointers = dense_to_csr(dense)
    width = len(dense[0])
    rebuilt = csr_to_dense(values, col_indices, row_pointers, width)

    print("values:       %s" % values)
    print("col_indices:  %s" % col_indices)
    print("row_pointers: %s" % row_pointers)
    print("row sums:     %s" % csr_row_sums(values, row_pointers))
    print("empty rows:   %s" % empty_row_indices(row_pointers))
    print("reconstructed:")
    print(format_matrix(rebuilt))
    print("round trip exact: %s" % matrices_equal(dense, rebuilt))

    return (values, col_indices, row_pointers), rebuilt


if __name__ == "__main__":
    main()

