def validate_square(matrix):
    """Check that matrix is a non-empty NxN list of lists of numbers."""
    n = len(matrix)
    if n == 0:
        raise ValueError("matrix must not be empty")
    for i in range(n):
        row = matrix[i]
        if len(row) != n:
            raise ValueError("row %d has length %d, expected %d" % (i, len(row), n))
        for j in range(n):
            if not isinstance(row[j], (int, float)) or isinstance(row[j], bool):
                raise ValueError("element (%d, %d) is not a number" % (i, j))
    return n


def copy_matrix(matrix):
    """Return a copy of matrix with all entries converted to float."""
    result = []
    for i in range(len(matrix)):
        result.append([float(x) for x in matrix[i]])
    return result


def to_row_echelon(matrix):
    """Reduce an NxN matrix to upper triangular form without pivoting."""
    n = validate_square(matrix)
    work = copy_matrix(matrix)
    for i in range(n - 1):
        pivot = work[i][i]
        if pivot == 0.0:
            raise ValueError("zero pivot at position (%d, %d)" % (i, i))
        for j in range(i, n):
            work[i][j] = work[i][j] / pivot
        for j in range(i + 1, n):
            factor = work[j][i]
            for k in range(i, n):
                work[j][k] -= factor * work[i][k]
    return work


