def prefix_widths(words):
    """Cumulative width of the first n words, each followed by one blank."""
    widths = [0]
    for i in range(len(words)):
        widths.append(widths[i] + len(words[i]) + 1)
    return widths


def line_width(widths, start, stop):
    """Width of the line holding words[start:stop] with single blanks between them."""
    return widths[stop] - widths[start] - 1


def validate(words, page_width):
    """Reject inputs for which no wrapping exists."""
    if page_width <= 0:
        raise ValueError("page_width must be positive")
    for i in range(len(words)):
        if not words[i]:
            raise ValueError("word %d is empty" % i)
        if len(words[i]) > page_width:
            raise ValueError("word %d (%r) is wider than the page" % (i, words[i]))


def justify_text(words, page_width):
    """Wrap words so that the sum of cubed trailing spaces per line is minimal."""
    validate(words, page_width)
    widths = prefix_widths(words)
    count = len(words)
    cost = [0] * (count + 1)
    breaks = [count] * (count + 1)
    for i in range(count - 1, -1, -1):
        best = None
        for j in range(i, count):
            width = line_width(widths, i, j + 1)
            if width > page_width:
                break
            candidate = (page_width - width) ** 3 + cost[j + 1]
            if best is None or candidate <= best:
                best = candidate
                breaks[i] = j + 1
        cost[i] = best
    lines = []
    start = 0
    while start < count:
        stop = breaks[start]
        lines.append(" ".join(words[start:stop]))
        start = stop
    return lines


def total_badness(lines, page_width):
    """Cost of an already wrapped paragraph."""
    total = 0
    for i in range(len(lines)):
        total += (page_width - len(lines[i])) ** 3
    return total


def report(words, page_width):
    """Render the optimal wrapping inside a frame, followed by its badness."""
    lines = justify_text(words, page_width)
    rule = "+" + "-" * page_width + "+"
    out = [rule]
    for i in range(len(lines)):
        out.append("|" + lines[i].ljust(page_width) + "| %d" % (i + 1))
    out.append(rule)
    out.append("badness = %d" % total_badness(lines, page_width))
    return "\n".join(out)


def main():
    samples = [
        (["a", "b", "c", "def"], 4),
        ("the quick brown fox jumps over the lazy dog".split(), 11),
        ("dynamic programming finds the least ragged paragraph".split(), 20),
    ]
    for words, page_width in samples:
        print(report(words, page_width))
        print()


if __name__ == "__main__":
    main()

