            width = line_width(widths, index, column + 1)
            if width > page_width:
                break
            candidate = (page_width - width) ** 3 + cost[column + 1]
            if best is None or candidate <= best:
                best = candidate
                breaks[index] = column + 1
        cost[index] = best
    lines = []
    start = 0
    while start < count:
        stop = breaks[start]
        lines.append(" ".join(words[start:stop]))
        start = stop
    return lines


def total_badness(lines, page_width):
    """Cost of an already wrapped paragraph."""
    total = 0
    for index in range(len(lines)):
        total += (page_width - len(lines[index])) ** 3
    return total


def report(words, page_width):
    """Render the optimal wrapping inside a frame, followed by its badness."""
    lines = justify_text(words, page_width)
    rule = "+" + "-" * page_width + "+"
    out = [rule]
    for index in range(len(lines)):
        out.append("|" + lines[index].ljust(page_width) + "| %d" % (index + 1))
    out.append(rule)
    out.append("badness = %d" % total_badness(lines, page_width))
    return "\n".join(out)


def main():
    samples = [
        (["a", "b", "c", "def"], 4),
        ("the quick brown fox jumps over the lazy dog".split(), 11),
        ("dynamic programming finds the least ragged paragraph".split(), 20),
    ]
    for words, page_width in samples:
        print(report(words, page_width))
        print()


if __name__ == "__main__":
    main()

