def validate_distance_matrix(matrix):
    """Check that the matrix is square, symmetric and non-negative; return its order."""
    total = len(matrix)
    if total < 2:
        raise ValueError("at least two nodes are required")
    for i in range(total):
        if len(matrix[i]) != total:
            raise ValueError("row %d does not have %d entries" % (i, total))
        if matrix[i][i] != 0:
            raise ValueError("diagonal entry %d must be zero" % i)
        for j in range(i + 1, total):
            if matrix[i][j] < 0:
                raise ValueError("negative distance at (%d, %d)" % (i, j))
            if matrix[i][j] != matrix[j][i]:
                raise ValueError("matrix is not symmetric at (%d, %d)" % (i, j))
    return total


def _held_karp(matrix):
    """Return (best cost, last node before returning to 0, parent table)."""
    total = validate_distance_matrix(matrix)
    dp = {}
    parent = {}
    for k in range(1, total):
        dp[((1 << k) | 1, k)] = matrix[0][k]
        parent[((1 << k) | 1, k)] = 0
    for i in range(3, total + 1):
        for j in range(1, 1 << total, 2):
            if bin(j).count("1") != i:
                continue
            for k in range(1, total):
                if not j & (1 << k):
                    continue
                rest = j & ~(1 << k)
                best, best_prev = None, None
                for prev in range(1, total):
                    if prev == k or not rest & (1 << prev):
                        continue
                    candidate = dp[(rest, prev)] + matrix[prev][k]
                    if best is None or candidate < best:
                        best, best_prev = candidate, prev
                dp[(j, k)] = best
                parent[(j, k)] = best_prev
    full = (1 << total) - 1
    best, last = None, None
    for k in range(1, total):
        candidate = dp[(full, k)] + matrix[k][0]
        if best is None or candidate < best:
            best, last = candidate, k
    return best, last, parent


def tsp_min_cost(distance_matrix):
    """Minimum cost of a tour that visits every node once and returns to node 0."""
    return _held_karp(distance_matrix)[0]


def tsp_tour(distance_matrix):
    """Minimum cost together with the node sequence realising it."""
    cost, last, parent = _held_karp(distance_matrix)
    bits = (1 << len(distance_matrix)) - 1
    path = [0]
    node = last
    while node != 0:
        path.append(node)
        previous = parent[(bits, node)]
        bits &= ~(1 << node)
        node = previous
    path.append(0)
    path.reverse()
    return cost, path


def format_matrix(matrix):
    """Render the distance matrix as aligned text rows."""
    total = len(matrix)
    widths = []
    for j in range(total):
        widths.append(max(len(str(matrix[i][j])) for i in range(total)))
    lines = []
    for i in range(total):
        cells = []
        for j in range(total):
            cells.append(str(matrix[i][j]).rjust(widths[j]))
        lines.append("  " + "  ".join(cells))
    return "\n".join(lines)


def main():
    distances = [
        [0, 10, 15, 20],
        [10, 0, 35, 25],
        [15, 35, 0, 30],
        [20, 25, 30, 0],
    ]
    print("Distance matrix:")
    print(format_matrix(distances))
    print("Minimum cost:", tsp_min_cost(distances))
    cost, path = tsp_tour(distances)
    print("Optimal tour:", " -> ".join(str(k) for k in path))
    for i in range(1, len(path)):
        print("  leg %d: %d -> %d costs %d"
              % (i, path[i - 1], path[i], distances[path[i - 1]][path[i]]))
    print("Total:", cost)


if __name__ == "__main__":
    main()

