def build_vandermonde(x_values, degree):
    """Return an M x (degree+1) matrix whose entry (row, col) is x_values[row] ** col."""
    if degree < 0:
        raise ValueError("degree must be non-negative")
    matrix = []
    for i in range(len(x_values)):
        x = float(x_values[i])
        row = []
        power = 1.0
        for j in range(degree + 1):
            row.append(power)
            power *= x
        matrix.append(row)
    return matrix


def evaluate_polynomial(vandermonde_matrix, coefficients):
    """Multiply the Vandermonde matrix by the coefficient vector, row by column."""
    width = len(coefficients)
    results = []
    for i in range(len(vandermonde_matrix)):
        row = vandermonde_matrix[i]
        if len(row) != width:
            raise ValueError("row %d does not match the coefficient count" % i)
        total = 0.0
        for k in range(width):
            total += row[k] * coefficients[k]
        results.append(total)
    return results


def polynomial_to_string(coefficients):
    """Render coefficients [a0, a1, a2, ...] as a human readable polynomial."""
    terms = []
    for i in range(len(coefficients)):
        coeff = coefficients[i]
        if coeff == 0.0:
            continue
        if i == 0:
            terms.append("%g" % coeff)
        elif i == 1:
            terms.append("%g*x" % coeff)
        else:
            terms.append("%g*x^%d" % (coeff, i))
    if not terms:
        return "0"
    terms.reverse()
    return " + ".join(terms)


def format_matrix(matrix):
    """Return the matrix as aligned text lines, one line per row."""
    lines = []
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append("%10.4f" % matrix[i][j])
        lines.append("[" + " ".join(cells) + "]")
    return "\n".join(lines)


def main():
    x_values = [-1.0, 0.5, 2.0, 3.5]
    coefficients = [2.0, -3.0, 1.0]
    degree = len(coefficients) - 1
    matrix = build_vandermonde(x_values, degree)
    y_values = evaluate_polynomial(matrix, coefficients)

    print("p(x) = " + polynomial_to_string(coefficients))
    print("Vandermonde matrix (%d x %d):" % (len(matrix), degree + 1))
    print(format_matrix(matrix))
    print("Evaluations:")
    for i in range(len(x_values)):
        print("  p(%6.2f) = %10.4f" % (x_values[i], y_values[i]))


if __name__ == "__main__":
    main()

