def validate(arr):
    """Check that the input is a list of integers, raising on anything else."""
    if not isinstance(arr, list):
        raise TypeError("expected a list, got %s" % type(arr).__name__)
    for i in range(len(arr)):
        value = arr[i]
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("list must contain only integers, found %r" % (value,))
    return arr


def gap_sequence(length):
    """The gaps shell_sort will visit for a list of the given length."""
    gaps = []
    gap = length // 2
    while gap > 0:
        gaps.append(gap)
        gap //= 2
    return gaps


def shell_sort(arr):
    """Sort a list of integers in place with the classic halving-gap shell sort."""
    validate(arr)
    gap = len(arr) // 2
    while gap > 0:
        for i in range(gap, len(arr)):
            current = arr[i]
            j = i
            while j >= gap and arr[j - gap] > current:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = current
        gap //= 2
    return arr


def is_sorted(arr):
    """True when every neighbouring pair is in non-decreasing order."""
    for i in range(1, len(arr)):
        if arr[i - 1] > arr[i]:
            return False
    return True


def count_inversions(arr):
    """Number of out-of-order pairs, a measure of how unsorted a list is."""
    total = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] > arr[j]:
                total += 1
    return total


def format_list(arr):
    """Render a list with every number right-aligned to a common width."""
    width = 0
    for i in range(len(arr)):
        if len(str(arr[i])) > width:
            width = len(str(arr[i]))
    cells = []
    for i in range(len(arr)):
        cells.append(str(arr[i]).rjust(width))
    return "[" + ", ".join(cells) + "]"


def main():
    datasets = [
        [12, 34, 54, 2, 3],
        [5, 4, 3, 2, 1],
        [42],
        [],
        [7, -3, 18, 0, 7, -3, 91, 12, 12, -50],
    ]
    for k in range(len(datasets)):
        data = datasets[k]
        gaps = gap_sequence(len(data))
        print("case %d" % (k + 1))
        print("  input      %s" % format_list(data))
        print("  inversions %d" % count_inversions(data))
        print("  gaps       %s" % (gaps if gaps else "none"))
        result = shell_sort(data)
        print("  output     %s" % format_list(result))
        print("  sorted     %s" % is_sorted(result))


if __name__ == "__main__":
    main()

