def max_sum_increasing_subsequence(arr):
    """Return the maximum sum of a strictly increasing subsequence of arr."""
    if not arr:
        return 0
    dp = list(arr)
    for i in range(len(arr)):
        for j in range(i):
            if arr[j] < arr[i] and dp[j] + arr[i] > dp[i]:
                dp[i] = dp[j] + arr[i]
    best = dp[0]
    for k in range(1, len(dp)):
        if dp[k] > best:
            best = dp[k]
    return best


def best_increasing_subsequence(arr):
    """Return the actual increasing subsequence achieving the maximum sum."""
    if not arr:
        return []
    dp = list(arr)
    parent = [-1] * len(arr)
    for i in range(len(arr)):
        for j in range(i):
            if arr[j] < arr[i] and dp[j] + arr[i] > dp[i]:
                dp[i] = dp[j] + arr[i]
                parent[i] = j
    end = 0
    for k in range(1, len(dp)):
        if dp[k] > dp[end]:
            end = k
    chain = []
    while end != -1:
        chain.append(arr[end])
        end = parent[end]
    chain.reverse()
    return chain


def parse_numbers(text):
    """Turn a comma/space separated string into a list of integers."""
    tokens = text.replace(",", " ").split()
    numbers = []
    for n in range(len(tokens)):
        token = tokens[n]
        try:
            numbers.append(int(token))
        except ValueError:
            raise ValueError("token %d is not an integer: %r" % (n + 1, token))
    return numbers


def format_report(arr):
    """Build a human readable summary for one input list."""
    total = max_sum_increasing_subsequence(arr)
    chain = best_increasing_subsequence(arr)
    pieces = []
    for i in range(len(chain)):
        pieces.append(str(chain[i]))
    return "%-28s sum=%-6d via %s" % (arr, total, " + ".join(pieces) or "-")


