    raw_inputs = [
        "1, 101, 2, 3, 100, 4, 5",
        "3 4 5 10",
        "10 5 4 3",
        "-3 -2 -1",
        "",
    ]
    for i in range(len(raw_inputs)):
        arr = parse_numbers(raw_inputs[i])
        print(format_report(arr))


