import random


def transpose(A):
    rows, cols = len(A), len(A[0])
    T = [[0.0] * rows for _ in range(cols)]
    for index in range(rows):
        for column in range(cols):
            T[column][index] = A[index][column]
    return T


def dot(u, v):
    total = 0.0
    for index in range(len(u)):
        total += u[index] * v[index]
    return total


def matmul(A, B):
    Bt = transpose(B)
    C = [[0.0] * len(Bt) for _ in range(len(A))]
    for index in range(len(A)):
        for column in range(len(Bt)):
            C[index][column] = dot(A[index], Bt[column])
    return C


def elementwise_divide(A, B, eps=1e-10):
    Q = [[0.0] * len(A[0]) for _ in range(len(A))]
    for index in range(len(A)):
        for column in range(len(A[0])):
            Q[index][column] = A[index][column] / (B[index][column] + eps)
    return Q


def elementwise_multiply_inplace(A, B):
    for index in range(len(A)):
        for column in range(len(A[0])):
            A[index][column] *= B[index][column]


def random_matrix(rows, cols):
    M = [[0.0] * cols for _ in range(rows)]
    for index in range(rows):
        for column in range(cols):
            M[index][column] = random.uniform(0.01, 0.1)
    return M


def frobenius_error(V, W, H):
    R = matmul(W, H)
    total = 0.0
    for index in range(len(V)):
        for column in range(len(V[0])):
            diff = V[index][column] - R[index][column]
            total += diff * diff
    return total ** 0.5


def nmf_factorize(V, k, iterations):
    rows, cols = len(V), len(V[0])
    W = random_matrix(rows, k)
    H = random_matrix(k, cols)
    for _ in range(iterations):
        Wt = transpose(W)
        elementwise_multiply_inplace(
            H, elementwise_divide(matmul(Wt, V), matmul(matmul(Wt, W), H)))
        Ht = transpose(H)
        elementwise_multiply_inplace(
            W, elementwise_divide(matmul(V, Ht), matmul(W, matmul(H, Ht))))
    return W, H


def format_matrix(M, name):
    lines = [name + ":"]
    for index in range(len(M)):
        lines.append("  " + "  ".join("%7.3f" % M[index][column] for column in range(len(M[0]))))
    return "\n".join(lines)


def main():
    random.seed(7)
    V = [[5.0, 3.0, 0.0, 1.0],
         [4.0, 0.0, 0.0, 1.0],
         [1.0, 1.0, 0.0, 5.0],
         [1.0, 0.0, 0.0, 4.0],
         [0.0, 1.0, 5.0, 4.0]]
    W, H = nmf_factorize(V, 2, 300)
    print(format_matrix(W, "W"))
    print(format_matrix(H, "H"))
    print(format_matrix(matmul(W, H), "W*H"))
    print("error: %.6f" % frobenius_error(V, W, H))


if __name__ == "__main__":
    main()

