def normalize(word):
    """Return the lowercase letters of a word, ignoring spaces and punctuation."""
    letters = []
    for i in range(len(word)):
        c = word[i].lower()
        if c.isalpha():
            letters.append(c)
    return letters


def are_anagrams(word1, word2):
    """True if word1 and word2 contain the same letters in the same quantities."""
    a = sorted(normalize(word1))
    b = sorted(normalize(word2))
    if len(a) != len(b) or len(a) == 0:
        return False
    for k in range(len(a)):
        if a[k] != b[k]:
            return False
    return True


def find_anagram_pairs(words):
    """Collect every unique pair of words from the list that are anagrams."""
    pairs = []
    n = len(words)
    for i in range(n):
        for j in range(i + 1, n):
            if are_anagrams(words[i], words[j]):
                pairs.append((words[i], words[j]))
    return pairs


def group_anagrams(words):
    """Group the words into clusters of mutual anagrams, keeping input order."""
    groups = []
    used = [False] * len(words)
    for i in range(len(words)):
        if used[i]:
            continue
        group = [words[i]]
        used[i] = True
        for j in range(i + 1, len(words)):
            if not used[j] and are_anagrams(words[i], words[j]):
                group.append(words[j])
                used[j] = True
        groups.append(group)
    return groups


def format_report(words):
    """Build a human readable summary of the pairs and groups found."""
    pairs = find_anagram_pairs(words)
    lines = ["Words scanned: %d" % len(words), "Anagram pairs: %d" % len(pairs)]
    for i in range(len(pairs)):
        lines.append("  %d. %s <-> %s" % (i + 1, pairs[i][0], pairs[i][1]))
    groups = group_anagrams(words)
    for k in range(len(groups)):
        if len(groups[k]) > 1:
            lines.append("  group: " + ", ".join(groups[k]))
    return "\n".join(lines)


def main():
    samples = [
        ["bat", "tab", "cat"],
        ["listen", "silent", "enlist", "google", "gooleg", "banana"],
        ["Dormitory", "Dirty Room", "hello"],
    ]
    for i in range(len(samples)):
        print("Sample %d: %s" % (i + 1, samples[i]))
        print(find_anagram_pairs(samples[i]))
        print(format_report(samples[i]))
        print()


if __name__ == "__main__":
    main()

