def validate_banded(M, bandwidth, name):
    """Check that M is square and that every entry outside the band is zero."""
    n = len(M)
    for i in range(n):
        if len(M[i]) != n:
            raise ValueError("%s is not square (row %d)" % (name, i))
    for i in range(n):
        for j in range(n):
            if abs(i - j) > bandwidth and M[i][j] != 0:
                raise ValueError("%s has a non-zero outside the band at (%d,%d)" % (name, i, j))
    return n


def banded_matrix_multiply(A, B, bandwidth):
    """Multiply two square banded matrices, touching only in-band elements."""
    if bandwidth < 0:
        raise ValueError("bandwidth must be non-negative")
    n = validate_banded(A, bandwidth, "A")
    if validate_banded(B, bandwidth, "B") != n:
        raise ValueError("A and B must have the same size")

    C = [[0] * n for _ in range(n)]
    for i in range(n):
        # The product can spread the band to twice its width.
        for j in range(max(0, i - 2 * bandwidth), min(n, i + 2 * bandwidth + 1)):
            total = 0
            lo = max(0, i - bandwidth, j - bandwidth)
            hi = min(n, i + bandwidth + 1, j + bandwidth + 1)
            for k in range(lo, hi):
                total += A[i][k] * B[k][j]
            C[i][j] = total
    return C


def make_banded(n, bandwidth, values):
    """Fill an n x n matrix inside the band, cycling through `values`."""
    M = [[0] * n for _ in range(n)]
    pos = 0
    for i in range(n):
        for j in range(max(0, i - bandwidth), min(n, i + bandwidth + 1)):
            M[i][j] = values[pos % len(values)]
            pos += 1
    return M


def format_matrix(M):
    width = 1
    for row in M:
        for value in row:
            width = max(width, len(str(value)))
    lines = []
    for i in range(len(M)):
        cells = []
        for j in range(len(M[i])):
            cells.append(str(M[i][j]).rjust(width))
        lines.append("[" + " ".join(cells) + "]")
    return "\n".join(lines)


def main():
    n = 6
    bandwidth = 1
    A = make_banded(n, bandwidth, [1, 2, 3])
    B = make_banded(n, bandwidth, [4, -1, 2, 5])
    C = banded_matrix_multiply(A, B, bandwidth)

    print("A =")
    print(format_matrix(A))
    print("B =")
    print(format_matrix(B))
    print("A * B =")
    print(format_matrix(C))

    filled = 0
    for i in range(n):
        for j in range(n):
            if C[i][j] != 0:
                filled += 1
    print("non-zero entries in product: %d of %d" % (filled, n * n))


if __name__ == "__main__":
    main()

