def matrix_size(M, name):
    n = len(M)
    for index in range(n):
        if len(M[index]) != n:
            raise ValueError("%s is not square: row %d has %d entries" % (name, index, len(M[index])))
    return n


def sequential_matrix(n, start=1):
    M = []
    for index in range(n):
        row = []
        for column in range(n):
            row.append(start + index * n + column)
        M.append(row)
    return M


def format_matrix(M):
    width = 0
    for row in M:
        for value in row:
            width = max(width, len("%g" % value))
    lines = []
    for index in range(len(M)):
        cells = []
        for column in range(len(M[index])):
            cells.append("%*g" % (width, M[index][column]))
        lines.append("[ " + "  ".join(cells) + " ]")
    return "\n".join(lines)


def accumulate_tile(C, A, B, row_start, row_stop, col_start, col_stop, dep_start, dep_stop):
    for index in range(row_start, row_stop):
        for column in range(col_start, col_stop):
            total = C[index][column]
            for key in range(dep_start, dep_stop):
                total += A[index][key] * B[key][column]
            C[index][column] = total


def block_matmul(A, B, block_size):
    n = matrix_size(A, "A")
    if matrix_size(B, "B") != n:
        raise ValueError("A and B must have the same size")
    if block_size <= 0:
        raise ValueError("block_size must be positive")

    C = []
    for index in range(n):
        row = []
        for column in range(n):
            row.append(0.0)
        C.append(row)

    for index in range(0, n, block_size):
        for column in range(0, n, block_size):
            for key in range(0, n, block_size):
                accumulate_tile(C, A, B,
                                index, min(index + block_size, n),
                                column, min(column + block_size, n),
                                key, min(key + block_size, n))

    for index in range(n):
        for column in range(n):
            C[index][column] = C[index][column] * 1.0
    return C


def main():
    n = 4
    A = sequential_matrix(n, 1)
    B = sequential_matrix(n, n * n + 1)
    C = block_matmul(A, B, 2)
    print("A =")
