def normalize_pattern(pattern):
    """Collapse runs of '*' into a single '*' (the match result is unchanged)."""
    out = []
    for i in range(len(pattern)):
        if pattern[i] == '*' and out and out[-1] == '*':
            continue
        out.append(pattern[i])
    return ''.join(out)


def pattern_summary(pattern):
    """Human readable breakdown of the characters that make up a pattern."""
    literals = 0
    singles = 0
    stars = 0
    for k in range(len(pattern)):
        c = pattern[k]
        if c == '*':
            stars += 1
        elif c == '?':
            singles += 1
        else:
            literals += 1
    return "%d literal(s), %d '?', %d '*'" % (literals, singles, stars)


def matching_prefix_lengths(text, pattern):
    """Lengths of the pattern prefixes that match the whole text."""
    t_len = len(text)
    p_len = len(pattern)

    dp = []
    for i in range(t_len + 1):
        dp.append([False] * (p_len + 1))
    dp[0][0] = True

    for j in range(1, p_len + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]

    for i in range(1, t_len + 1):
        for j in range(1, p_len + 1):
            pc = pattern[j - 1]
            if pc == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif pc == '?' or pc == text[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    lengths = []
    for n in range(p_len + 1):
        if dp[t_len][n]:
            lengths.append(n)
    return lengths


def is_wildcard_match(text, pattern):
    """True if pattern (with '?' and '*' wildcards) matches the entire text."""
    if not isinstance(text, str) or not isinstance(pattern, str):
        raise TypeError('text and pattern must both be strings')
    compact = normalize_pattern(pattern)
    return len(compact) in matching_prefix_lengths(text, compact)


def main():
    cases = [
        ('adceb', '*a*b'),
        ('aa', 'a'),
        ('cb', '?a'),
        ('abcdef', 'a?c*f'),
        ('', '***'),
        ('mississippi', 'm*iss*p?'),
    ]
    for n in range(len(cases)):
        text, pattern = cases[n]
        compact = normalize_pattern(pattern)
        prefixes = matching_prefix_lengths(text, compact)
        print('%d. text=%-12r pattern=%-8r -> %s' %
              (n + 1, text, pattern, is_wildcard_match(text, pattern)))
        print('   normalized=%r (%s)' % (compact, pattern_summary(compact)))
        print('   matching prefix lengths: %s' % (prefixes,))


if __name__ == '__main__':
    main()

