def validate_square(matrix):
    n = len(matrix)
    for i in range(n):
        if len(matrix[i]) != n:
            raise ValueError("row %d has %d entries, expected %d" % (i, len(matrix[i]), n))
        for j in range(n):
            if not isinstance(matrix[i][j], (int, float)):
                raise TypeError("entry (%d, %d) is not numeric" % (i, j))
    if n == 0:
        raise ValueError("matrix must contain at least one row")
    return n


def crout_lu(matrix):
    n = validate_square(matrix)
    lower = []
    upper = []
    for i in range(n):
        lower.append([0.0 for j in range(n)])
        upper.append([0.0 for j in range(n)])
    for i in range(n):
        upper[i][i] = 1.0
    for j in range(n):
        for i in range(j, n):
            total = 0.0
            for k in range(j):
                total += lower[i][k] * upper[k][j]
            lower[i][j] = matrix[i][j] - total
        if lower[j][j] == 0.0:
            raise ZeroDivisionError("matrix is singular at pivot %d" % j)
        for i in range(j + 1, n):
            total = 0.0
            for k in range(j):
                total += lower[j][k] * upper[k][i]
            upper[j][i] = (matrix[j][i] - total) / lower[j][j]
    for i in range(n):
        for j in range(n):
            lower[i][j] = round(lower[i][j], 3)
            upper[i][j] = round(upper[i][j], 3)
    return lower, upper


def multiply(a, b):
    n = len(a)
    product = []
    for i in range(n):
        row = []
        for j in range(n):
            total = 0.0
            for k in range(n):
                total += a[i][k] * b[k][j]
            row.append(round(total, 3))
        product.append(row)
    return product


def format_matrix(name, matrix):
    lines = [name + ":"]
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append("%8.3f" % matrix[i][j])
        lines.append("  [" + " ".join(cells) + "]")
    return "\n".join(lines)


def main():
    samples = [
        [[4, 3], [6, 3]],
        [[2, -1, -2], [-4, 6, 3], [-4, -2, 8]],
    ]
    for i, matrix in enumerate(samples):
        lower, upper = crout_lu(matrix)
        print("Matrix #%d" % (i + 1))
        print(format_matrix("A", matrix))
        print(format_matrix("L", lower))
        print(format_matrix("U", upper))
        print(format_matrix("L * U", multiply(lower, upper)))
        print()


if __name__ == "__main__":
    main()

