            coeffs.append("%+.1f*x%d" % (A[i][j], j + 1))
        print("  " + " ".join(coeffs) + " = %.1f" % b[i])

    solution = jacobi_solve(A, b, 25)
    print("Solution: " + format_solution(solution))


