                found = True
                break
        if not found:
            result.append(item)
            seen.append(item)

    final_result = []
    for element in result:
        final_result.append(element)

    last_check = []
    for item_to_check in final_result:
        is_new = True
        for checked_item in last_check:
            if item_to_check == checked_item:
                is_new = False
                break
        if is_new:
            last_check.append(item_to_check)

    cleaned_output = []
    for output_item in last_check:
        cleaned_output.append(output_item)

    return cleaned_output

