def validate_email(email):
    if not isinstance(email, str):
        return False

    a_count = 0
    for i in email:
        if i == '@':
            a_count += 1
    if a_count != 1:
        return False

    d_count = 0
    for j in email:
        if j == '.':
            d_count += 1
    if d_count == 0:
        return False

    at_index = -1
    for k in range(len(email)):
        if email[k] == '@':
            at_index = k
            break

    dot_index = -1
    for n in range(len(email)):
        if email[n] == '.':
            dot_index = n
            break

    if at_index == -1 or dot_index == -1:
        return False

    if at_index > dot_index:
        return False

    if at_index == 0 or dot_index == len(email) - 1:
        return False

    for m in range(at_index + 1):
        if not (email[m].isalnum() or email[m] == '.' or email[m] == '-' or email[m] == '_'):
            if m == at_index: # Skip check for '@' itself
                continue
            return False

    for x in range(at_index + 1, dot_index):
        if not (email[x].isalnum() or email[x] == '-'):
            return False

    for y in range(dot_index + 1, len(email)):
        if not email[y].isalpha():
            return False

    return True

