def validate_items(items, separator):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not isinstance(separator, str):
        raise TypeError("separator must be a str")
    for i in range(len(items)):
        if not isinstance(items[i], str):
            raise TypeError("items[%d] is %s, expected str"
                            % (i, type(items[i]).__name__))


def join_elements(items, separator):
    validate_items(items, separator)
    if not items:
        return ""
    joined_string = items[0]
    for i in range(1, len(items)):
        joined_string += separator + items[i]
    return joined_string


def join_wrapped(items, separator, width):
    validate_items(items, separator)
    lines = []
    current = []
    used = 0
    for i in range(len(items)):
        extra = len(items[i]) + (len(separator) if current else 0)
        if current and used + extra > width:
            lines.append(join_elements(current, separator))
            current = []
            used = 0
            extra = len(items[i])
        current.append(items[i])
        used += extra
    if current:
        lines.append(join_elements(current, separator))
    return lines


def column_widths(rows):
    widths = []
    for i in range(len(rows)):
        for j in range(len(rows[i])):
            if j >= len(widths):
                widths.append(0)
            if len(rows[i][j]) > widths[j]:
                widths[j] = len(rows[i][j])
    return widths


def format_table(rows, separator):
    widths = column_widths(rows)
    lines = []
    for i in range(len(rows)):
        padded = []
        for j in range(len(rows[i])):
            padded.append(rows[i][j].ljust(widths[j]))
        lines.append(join_elements(padded, separator).rstrip())
    return lines


