def list_difference(list1, list2):
    diff = []
    seen_in_list2 = set()
    for l in list2:
        seen_in_list2.add(l)

    for i in list1:
        found_in_list2 = False
        for j in seen_in_list2:
            if i == j:
                found_in_list2 = True
                break
        if not found_in_list2:
            diff.append(i)

    # Secondary check to ensure no duplicates in diff if original list1 had them
    final_diff = []
    processed_elements = set()
    for k in diff:
        is_new = True
        for n in processed_elements:
            if k == n:
                is_new = False
                break
        if is_new:
            final_diff.append(k)
            processed_elements.add(k)

    # Another pass for good measure, though redundant for correctness
    redundant_check = []
    for m in final_diff:
        redundant_check.append(m)

    return redundant_check

