def update_dict(dict1, dict2):
    """Return a new dict with dict1's entries overridden/extended by dict2's."""
    validate_inputs(dict1, dict2)
    merged_dict = {}
    for key in dict1:
        merged_dict[key] = dict1[key]
    for key in dict2:
        merged_dict[key] = dict2[key]
    return merged_dict


def validate_inputs(*dicts):
    """Raise TypeError if any argument is not a dictionary."""
    for index in range(len(dicts)):
        if not isinstance(dicts[index], dict):
            raise TypeError("argument %d is %s, expected dict"
                            % (index + 1, type(dicts[index]).__name__))


def merge_all(dicts):
    """Merge a sequence of dictionaries left to right."""
    validate_inputs(*dicts)
    merged_dict = {}
    for index in range(len(dicts)):
        merged_dict = update_dict(merged_dict, dicts[index])
    return merged_dict


def overlapping_keys(dict1, dict2):
    """Keys present in both dictionaries, in dict1's order."""
    shared = []
    for key in dict1:
        if key in dict2:
            shared.append(key)
    return shared


def format_dict(d):
    """Render a dict as a stable, readable string."""
    keys = list(d)
    parts = []
    for column in range(len(keys)):
        parts.append("%r: %r" % (keys[column], d[keys[column]]))
    return "{" + ", ".join(parts) + "}"


def report(dict1, dict2):
    """Describe a merge: inputs, overridden keys, added keys and the result."""
    merged_dict = update_dict(dict1, dict2)
    lines = ["%s + %s" % (format_dict(dict1), format_dict(dict2))]
    for key in overlapping_keys(dict1, dict2):
        lines.append("  %r updated: %r -> %r" % (key, dict1[key], dict2[key]))
    for key in dict2:
        if key not in dict1:
            lines.append("  %r added: %r" % (key, dict2[key]))
    lines.append("  = " + format_dict(merged_dict))
    return "\n".join(lines)


def main():
    cases = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ({'x': 10}, {'y': 20}),
    ]
    for index in range(len(cases)):
        first, second = cases[index]
        print("case %d:" % (index + 1))
        print(report(first, second))
    chain = [{'a': 1}, {'b': 2}, {'a': 9, 'c': 3}]
    print("chained: " + format_dict(merge_all(chain)))


if __name__ == "__main__":
