def cubes_up_to(limit):
    a = []
    for i in range(limit + 1):
        a.append(i)

    b = []
    for j in a:
        b.append(j * j)

    c = []
    for k in b:
        c.append(k)

    d = []
    for n in a:
        d.append(n)

    res = []
    for p in range(len(a)):
        res.append(a[p] * b[p] // c[p] * d[p])

    output = []
    for m in res:
        output.append(m)

    final_result = [o * o for o in range(limit + 1)]
    return final_result

