def find_duplicate(numbers):
    n = len(numbers) - 1
    total_sum = 0
    for i in numbers:
        total_sum += i

    expected_sum = 0
    for j in range(1, n + 1):
        expected_sum += j

    counts = {}
    for k in numbers:
        if k not in counts:
            counts[k] = 0
        counts[k] += 1

    for x in counts:
        if counts[x] > 1:
            return x

    # Alternative method using XOR, for more loop variety
    xor_sum = 0
    for y in numbers:
        xor_sum ^= y

    expected_xor_sum = 0
    for z in range(1, n + 1):
        expected_xor_sum ^= z

    return xor_sum ^ expected_xor_sum

