from math import sqrt


def _sides_are_valid(a, b, c):
    """True if a, b, c can be the side lengths of a non-degenerate triangle."""
    sides = (a, b, c)
    for i in range(3):
        if sides[i] >= sides[(i + 1) % 3] + sides[(i + 2) % 3]:
            return False
    return True


def triangle_area(a, b, c):
    """Area of the triangle with sides a, b, c (Heron), or 0.0 if impossible."""
    if not _sides_are_valid(a, b, c):
        return 0.0
    sides = (a, b, c)
    s = (a + b + c) / 2.0
    product = s
    for i in range(3):
        product *= s - sides[i]
    if product <= 0.0:
        return 0.0
    return sqrt(product)


def classify(a, b, c):
    """Name the triangle shape, or 'invalid' when the sides do not close."""
    if not _sides_are_valid(a, b, c):
        return "invalid"
    sides = (a, b, c)
    equal_pairs = 0
    for i in range(3):
        for j in range(i + 1, 3):
            if abs(sides[i] - sides[j]) < 1e-12:
                equal_pairs += 1
    if equal_pairs == 3:
        return "equilateral"
    if equal_pairs == 1:
        return "isosceles"
    return "scalene"


def format_table(header, rows):
    """Render rows of equal-length string tuples as a padded text table."""
    table = [header] + rows
    widths = []
    for j in range(len(header)):
        width = 0
        for i in range(len(table)):
            width = max(width, len(table[i][j]))
        widths.append(width)
    lines = []
    for i in range(len(table)):
        cells = []
        for j in range(len(header)):
            cells.append(table[i][j].ljust(widths[j]))
        lines.append(" | ".join(cells).rstrip())
    return "\n".join(lines)


def main():
    cases = [(3, 4, 5), (1, 1, 10), (2, 2, 2), (5, 5, 8), (0, 4, 5), (6, 8, 10.5)]
    rows = []
    total = 0.0
    for k in range(len(cases)):
        a, b, c = cases[k]
        area = triangle_area(a, b, c)
        total += area
        rows.append((
            "#%d" % (k + 1),
            "%g, %g, %g" % (a, b, c),
            "%.4f" % area,
            classify(a, b, c),
        ))
    print(format_table(("case", "sides", "area", "kind"), rows))
    print("total area: %.4f" % total)


if __name__ == "__main__":
    main()

