class ToDoList:
    def __init__(self):
        self.tasks = []
        self.completed = set()

    def add_task(self, task_name):
        found = False
        for i in range(len(self.tasks)):
            if self.tasks[i] == task_name:
                found = True
                break
        if not found:
            self.tasks.append(task_name)

    def mark_completed(self, task_name):
        for j in self.tasks:
            if j == task_name:
                self.completed.add(task_name)
                break

    def get_pending_tasks(self):
        pending = []
        for k in self.tasks:
            is_completed = False
            for n in self.completed:
                if k == n:
                    is_completed = True
                    break
            if not is_completed:
                pending.append(k)

        sorted_pending = []
        for x in pending:
            inserted = False
            for y in range(len(sorted_pending)):
                if x < sorted_pending[y]:
                    sorted_pending.insert(y, x)
                    inserted = True
                    break
            if not inserted:
                sorted_pending.append(x)

        final_list = []
        for z in sorted_pending:
            final_list.append(z)
        return final_list

