ALIGNMENTS = ("<", ">", "<")

def tokenize(expression):
    """Split an expression like '10 - 2 + 3' into [10, '-', 2, '+', 3]."""
    text = expression.replace(" ", "")
    tokens = []
    digits = ""
    for i in range(len(text)):
        c = text[i]
        if c.isdigit():
            digits += c
        elif c in "+-":
            if not digits:
                raise ValueError("missing operand before %r at position %d" % (c, i))
            tokens.append(int(digits))
            tokens.append(c)
            digits = ""
        else:
            raise ValueError("invalid character %r at position %d" % (c, i))
    if not digits:
        raise ValueError("expression must end with a number: %r" % expression)
    tokens.append(int(digits))
    return tokens

def running_totals(tokens):
    """Fold the tokens left to right, keeping every intermediate total."""
    totals = [tokens[0]]
    for j in range(1, len(tokens), 2):
        step = tokens[j + 1] if tokens[j] == "+" else -tokens[j + 1]
        totals.append(totals[-1] + step)
    return totals

def simple_calculator(expression):
    """Parse an addition/subtraction expression and return the integer result."""
    return running_totals(tokenize(expression))[-1]

def trace(tokens):
    """Render the evaluation as '5 + 3 = 8 - 1 = 7'."""
    totals = running_totals(tokens)
    parts = [str(tokens[0])]
    for k in range(1, len(tokens), 2):
        parts.append("%s %s = %d" % (tokens[k], tokens[k + 1], totals[k // 2 + 1]))
    return " ".join(parts)

def column_widths(rows):
    """Measure the widest cell of each column of a table of strings."""
    widths = [0] * len(rows[0])
    for row in rows:
        for j in range(len(row)):
            widths[j] = max(widths[j], len(row[j]))
    return widths

def format_row(row, widths):
    """Pad every cell of a row according to its column alignment."""
    cells = []
    for j in range(len(row)):
        if ALIGNMENTS[j] == ">":
            cells.append(row[j].rjust(widths[j]))
        else:
            cells.append(row[j].ljust(widths[j]))
    return "  ".join(cells).rstrip()

def describe(expression):
    """Return the expression, its result and its evaluation trace as strings."""
    try:
        tokens = tokenize(expression)
    except ValueError as error:
        return (expression, "error", str(error))
    return (expression, str(running_totals(tokens)[-1]), trace(tokens))

def format_report(expressions):
    """Build numbered, column-aligned lines for the given expressions."""
    rows = [describe(text) for text in expressions]
    widths = column_widths(rows)
    return ["%2d. %s" % (number, format_row(row, widths))
            for number, row in enumerate(rows, 1)]

def main():
    samples = ["5+3", "10-2", "1+2+3+4", "100 - 45 + 5", "7", "8+", "2*3"]
    for line in format_report(samples):
        print(line)

if __name__ == "__main__":
    main()

