    """Return the record with the given id, or None if there is no such record."""
    for index in range(len(db)):
        if db[index]['id'] == employee_id:
            return db[index]
    return None


def department_counts(db):
    """Map each department name to the number of employees working in it."""
    counts = {}
    for index in range(len(db)):
        dept = db[index]['department']
        counts[dept] = counts.get(dept, 0) + 1
    return counts


def format_table(db):
    """Render the database as an aligned text table."""
    headers = ['ID', 'NAME', 'DEPARTMENT']
    rows = [headers]
    for index in range(len(db)):
        record = db[index]
        rows.append([str(record['id']), record['name'], record['department']])

    widths = []
    for column in range(len(headers)):
        widest = 0
        for index in range(len(rows)):
            if len(rows[index][column]) > widest:
                widest = len(rows[index][column])
        widths.append(widest)

    lines = []
    for index in range(len(rows)):
        cells = []
        for column in range(len(headers)):
            cells.append(rows[index][column].ljust(widths[column]))
        lines.append('  '.join(cells).rstrip())
    return '\n'.join(lines)


def main():
    requests = [
        (1, 'Alice', 'HR'),
        (2, 'Bob', 'IT'),
        (3, 'Dana', 'IT'),
        (1, 'Charlie', 'Sales'),
        (4, 'Eve', 'HR'),
    ]

    db = []
    for index in range(len(requests)):
        employee_id, name, department = requests[index]
        if add_employee(db, employee_id, name, department):
            print('added %d: %s (%s)' % (employee_id, name, department))
        else:
            existing = find_employee(db, employee_id)
            print('rejected %d: id taken by %s' % (employee_id, existing['name']))

    print()
    print(format_table(db))
    print()

    counts = department_counts(db)
    names = sorted(counts)
    for index in range(len(names)):
        print('%s: %d employee(s)' % (names[index], counts[names[index]]))


if __name__ == '__main__':
