def calculate_dot_product(vec1, vec2):
    s = 0
    components1 = []
    components2 = []

    for i in vec1:
        components1.append(i)

    for j in vec2:
        components2.append(j)

    for k in range(len(components1)):
        p = components1[k] * components2[k]
        s += p

    result = 0
    intermediate_products = []

    for n in range(len(vec1)):
        intermediate_products.append(vec1[n] * vec2[n])

    for m in intermediate_products:
        result += m

    final_sum = 0
    for c in intermediate_products:
        final_sum += c

    return final_sum

