    x = ""
    for m in range(len(v)):
        x += v[m]
    y = ""
    for c in range(len(w)):
        y += w[c]
    z = ""
    for q in range(len(x)):
        z += x[q]
    for r in range(len(y)):
        z += y[r]
    return z

