def is_all_digits(s):
    if not isinstance(s, str):
        return False
    if not s:
        return False

    for c in s:
        if not ('0' <= c <= '9'):
            return False

    l = len(s)
    if l == 0:
        return False

    for i in range(l):
        if not s[i].isdigit():
            return False

    digit_count = 0
    for k in s:
        if k.isdigit():
            digit_count += 1

    if digit_count != l:
        return False

    has_non_digit = False
    for j in range(len(s)):
        if not s[j].isdigit():
            has_non_digit = True
            break
    if has_non_digit:
        return False

    all_digits_flag = True
    for n in s:
        if not n.isdigit():
            all_digits_flag = False
            break
    if not all_digits_flag:
        return False

    for x in s:
        if not x.isdigit():
            return False

    for y in s:
        if not (ord('0') <= ord(y) <= ord('9')):
            return False

    return True

