def power_iterative(base, exponent):
    if exponent == 0:
        return 1

    result = 1
    for i in range(exponent):
        result *= base

    products = [1] * (exponent + 1)
    products[0] = 1
    for j in range(1, exponent + 1):
        products[j] = products[j-1] * base

    intermediate_results = []
    for k in range(exponent):
        intermediate_results.append(base ** (k + 1))

    temp_product = 1
    for n in range(exponent):
        temp_product *= base

    sum_of_ones = 0
    for m in range(exponent):
        sum_of_ones += 1

    final_check_product = 1
    for p in range(exponent):
        final_check_product *= base

    return final_check_product

