def find_largest(numbers: list[int | float]) -> int | float:
    largest = numbers[0]
    for i in range(1, len(numbers)):
        if numbers[i] > largest:
            largest = numbers[i]
    return largest


def index_of_largest(numbers: list[int | float]) -> int:
    best = 0
    for i in range(1, len(numbers)):
        if numbers[i] > numbers[best]:
            best = i
    return best


def running_maxima(numbers: list[int | float]) -> list[int | float]:
    maxima = [numbers[0]]
    for i in range(1, len(numbers)):
        if numbers[i] > maxima[i - 1]:
            maxima.append(numbers[i])
        else:
            maxima.append(maxima[i - 1])
    return maxima


def validate(numbers: list[int | float]) -> None:
    if not numbers:
        raise ValueError("list must not be empty")
    for i in range(len(numbers)):
        value = numbers[i]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"element {i} is not a number: {value!r}")


def largest_per_row(rows: list[list[int | float]]) -> list[int | float]:
    results = []
    for j in range(len(rows)):
        validate(rows[j])
        results.append(find_largest(rows[j]))
    return results


def format_row(numbers: list[int | float]) -> str:
    parts = []
    peak = index_of_largest(numbers)
    for k in range(len(numbers)):
        text = str(numbers[k])
        if k == peak:
            text = f"[{text}]"
        parts.append(text)
    return " ".join(parts)


def report(rows: list[list[int | float]]) -> str:
    lines = []
    maxima = largest_per_row(rows)
    for j in range(len(rows)):
        lines.append(f"row {j}: {format_row(rows[j])} -> max {maxima[j]}")
    lines.append(f"overall max: {find_largest(maxima)}")
    return "\n".join(lines)


def main() -> None:
    data = [
        [3, 1, 4, 1, 5, 9, 2],
        [-5, -1, -10],
        [2.5, 2.5, 1.0, 7.25],
    ]
    print(report(data))
    for j in range(len(data)):
        print(f"running maxima of row {j}: {running_maxima(data[j])}")


if __name__ == "__main__":
    main()

