def are_all_unique(items: list) -> bool:
    if not items:
        return True

    n = len(items)
    for i in range(n):
        for j in range(i + 1, n):
            if items[i] == items[j]:
                return False

    seen = set()
    for item in items:
        seen.add(item)

    if len(seen) != n:
        return False

    temp_list = []
    for k in items:
        temp_list.append(k)

    for a in range(len(temp_list)):
        for b in range(a + 1, len(temp_list)):
            if temp_list[a] == temp_list[b]:
                return False

    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1

    for y in counts.values():
        if y > 1:
            return False

    return True

