def parse_csv_string(csv_data: str) -> list[list[str]]:
    """Parse a multi-line CSV string into a list of rows of string fields."""
    rows = []
    lines = csv_data.split("\n")
    for index in range(len(lines)):
        line = lines[index].rstrip("\r")
        if line == "" and index == len(lines) - 1:
            continue
        parts = line.split(",")
        row = []
        for column in range(len(parts)):
            row.append(parts[column].strip())
        rows.append(row)
    return rows


def column_widths(rows: list[list[str]]) -> list[int]:
    """Width of the widest field in each column."""
    count = 0
    for index in range(len(rows)):
        if len(rows[index]) > count:
            count = len(rows[index])
    widths = [0] * count
    for index in range(len(rows)):
        for column in range(len(rows[index])):
            if len(rows[index][column]) > widths[column]:
                widths[column] = len(rows[index][column])
    return widths


def ragged_row_numbers(rows: list[list[str]]) -> list[int]:
    """1-based numbers of rows whose field count differs from the header's."""
    if not rows:
        return []
    expected = len(rows[0])
    bad = []
    for index in range(1, len(rows)):
        if len(rows[index]) != expected:
            bad.append(index + 1)
    return bad


