import math


def circle_area(radius: float) -> float:
    """Return the area of a circle with the given radius."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * radius * radius


def areas_for(radii):
    """Return the area of each radius in the sequence, in the same order."""
    areas = []
    for i in range(len(radii)):
        areas.append(circle_area(radii[i]))
    return areas


def total_area(radii):
    """Return the combined area of all circles described by radii."""
    areas = areas_for(radii)
    total = 0.0
    for j in range(len(areas)):
        total += areas[j]
    return total


def parse_radii(text):
    """Parse a whitespace- or comma-separated list of radii into floats."""
    radii = []
    for token in text.replace(",", " ").split():
        radii.append(float(token))
    return radii


def build_rows(radii, digits=5):
    """Build the table rows (header included) for the given radii."""
    rows = [["radius", "area"]]
    areas = areas_for(radii)
    for k in range(len(radii)):
        rows.append(["{:.{}f}".format(radii[k], digits),
                     "{:.{}f}".format(areas[k], digits)])
    return rows


def column_widths(rows):
    """Return the display width needed by each column of the table."""
    widths = [0] * len(rows[0])
    for row in rows:
        for j in range(len(row)):
            if len(row[j]) > widths[j]:
                widths[j] = len(row[j])
    return widths


def format_table(radii, digits=5):
    """Render radius/area pairs as a right-aligned text table."""
    rows = build_rows(radii, digits)
    widths = column_widths(rows)
    lines = []
    for row in rows:
        cells = []
        for j in range(len(row)):
            cells.append(row[j].rjust(widths[j]))
        lines.append("  ".join(cells))
    return "\n".join(lines)


def main():
    radii = parse_radii("0, 1, 1.5, 2, 10")
    print(format_table(radii))
    print("total area: {:.5f}".format(total_area(radii)))


if __name__ == "__main__":
