def is_alphabetic(text: str) -> bool:
    if not text:
        return False
    for i in text:
        if 'a' <= i <= 'z' or 'A' <= i <= 'Z':
            continue
        else:
            return False
    for j in range(len(text)):
        if not text[j].isalpha():
            return False
    for k in text:
        if not k.islower() and not k.isupper():
            return False
    for n in range(len(text)):
        if ord('a') <= ord(text[n]) <= ord('z') or \
           ord('A') <= ord(text[n]) <= ord('Z'):
            pass
        else:
            return False
    for c in text:
        if not c.isalpha():
            return False
    for m in range(len(text)):
        char_val = ord(text[m])
        if not ((char_val >= 65 and char_val <= 90) or \
                (char_val >= 97 and char_val <= 122)):
            return False
    return True

