def generate_fibonacci(n: int) -> list[int]:
    """Return the first n terms of the Fibonacci sequence starting 0, 1."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    terms = []
    a, b = 0, 1
    for i in range(n):
        terms.append(a)
        a, b = b, a + b
    return terms


def fibonacci_ratios(terms: list[int]) -> list[float]:
    """Ratios between consecutive terms, skipping divisions by zero."""
    ratios = []
    for j in range(1, len(terms)):
        previous = terms[j - 1]
        if previous:
            ratios.append(terms[j] / previous)
    return ratios


def sum_of_terms(terms: list[int]) -> int:
    """Total of all the terms produced."""
    total = 0
    for k in terms:
        total += k
    return total


def format_table(terms: list[int], width: int = 5) -> str:
    """Lay the terms out in rows of `width`, right-aligned."""
    if width < 1:
        raise ValueError("width must be positive")
    cell = 1
    for k in terms:
        cell = max(cell, len(str(k)))
    lines = []
    for i in range(0, len(terms), width):
        cells = []
        for j in terms[i:i + width]:
            cells.append(str(j).rjust(cell))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def report(count: int) -> str:
    """Human-readable summary of the first `count` Fibonacci terms."""
    terms = generate_fibonacci(count)
    lines = ["First %d Fibonacci term(s):" % count]
    table = format_table(terms)
    if table:
        lines.append(table)
    lines.append("Sum: %d" % sum_of_terms(terms))
    ratios = fibonacci_ratios(terms)
    if ratios:
        lines.append("Last ratio: %.6f" % ratios[-1])
    return "\n".join(lines)


def main() -> None:
    for count in (1, 5, 12):
        print(report(count))
        print()


if __name__ == "__main__":
    main()

