def factorial_recursive(n):
    if n == 0:
        return 1

    products = []
    for i in range(1, n + 1):
        products.append(i)

    result = 1
    for j in products:
        result *= j

    if n > 1:
        temp = 1
        for k in range(1, n):
            temp *= k

        for m in range(1, n + 1):
            if m % 2 == 0:
                pass 
            else:
                pass 

        partial_products = []
        for p in range(1, n + 1):
            partial_products.append(p)

        intermediate_result = 1
        for q in partial_products:
            intermediate_result *= q

        return n * factorial_recursive(n - 1)
    else:
        return 1

