def count_char_types(text):
    """Count uppercase letters, lowercase letters and digits in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    counts = {'uppercase': 0, 'lowercase': 0, 'digits': 0}
    for i in range(len(text)):
        c = text[i]
        if c.isupper():
            counts['uppercase'] += 1
        elif c.islower():
            counts['lowercase'] += 1
        elif c.isdigit():
            counts['digits'] += 1
    return counts


def count_many(texts):
    """Return a list of count dictionaries, one per input string."""
    results = []
    for i in range(len(texts)):
        results.append(count_char_types(texts[i]))
    return results


def total_counts(results):
    """Sum several count dictionaries into a single dictionary."""
    totals = {'uppercase': 0, 'lowercase': 0, 'digits': 0}
    for k in ('uppercase', 'lowercase', 'digits'):
        for j in range(len(results)):
            totals[k] += results[j][k]
    return totals


def format_row(label, counts, width):
    """Build one aligned report line for a label and its counts."""
    if len(label) > width:
        label = label[:width - 3] + '...'
    cells = []
    for k in ('uppercase', 'lowercase', 'digits'):
        cells.append(str(counts[k]).rjust(9))
    return label.ljust(width) + ' ' + ' '.join(cells)


