def _index_of(collection: list, value) -> int:
    """Return the position of value in collection, or -1 when it is absent."""
    for i in range(len(collection)):
        if collection[i] == value:
            return i
    return -1


def find_unique_elements(input_list: list) -> list:
    """Return the elements of input_list without repetitions, order preserved."""
    if not isinstance(input_list, list):
        raise TypeError("find_unique_elements expects a list")
    seen = set()
    seen_unhashable = []
    result = []
    for i in range(len(input_list)):
        value = input_list[i]
        try:
            if value in seen:
                continue
            seen.add(value)
        except TypeError:
            if _index_of(seen_unhashable, value) >= 0:
                continue
            seen_unhashable.append(value)
        result.append(value)
    return result


def count_occurrences(input_list: list) -> list:
    """Pair every unique element with how many times it appears."""
    unique = find_unique_elements(input_list)
    counts = []
    for i in range(len(unique)):
        n = 0
        for j in range(len(input_list)):
            if input_list[j] == unique[i]:
                n += 1
        counts.append((unique[i], n))
    return counts


def find_duplicates(input_list: list) -> list:
    """Unique elements that occur more than once, in order of first appearance."""
    duplicates = []
    for value, count in count_occurrences(input_list):
        if count > 1:
            duplicates.append(value)
    return duplicates


def format_report(input_list: list) -> str:
    """Build a human readable summary of a list's unique and repeated values."""
    lines = ["original : %r" % (input_list,),
             "unique   : %r" % (find_unique_elements(input_list),),
             "repeated : %r" % (find_duplicates(input_list),)]
    pairs = count_occurrences(input_list)
    for k in range(len(pairs)):
        value, count = pairs[k]
        lines.append("  %d. %r appears %d time(s)" % (k + 1, value, count))
    return "\n".join(lines)


def main() -> None:
    datasets = [
        [1, 2, 2, 3, 1, 4],
        ['a', 'b', 'a', 'c'],
        [],
        [[1], [2], [1], (3, 4), (3, 4)],
    ]
    for i in range(len(datasets)):
        print("dataset %d" % (i + 1))
        print(format_report(datasets[i]))
        print()


if __name__ == "__main__":
    main()

