        if c == " ":
            if current:
                words.append(current)
                current = ""
        else:
            current += c
    if current:
        words.append(current)
    return words


def count_words(sentence: str) -> int:
    """Count the words of a sentence, where words are separated by spaces."""
    return len(split_words(sentence))


def count_letters(word: str) -> int:
    """Count the alphabetic characters of a single word."""
    total = 0
    for k in range(len(word)):
        if word[k].isalpha():
            total += 1
    return total


def longest_word(words: list) -> str:
    """Return the first word of maximal length, or '' for an empty list."""
    best = ""
    for j in range(len(words)):
        if len(words[j]) > len(best):
            best = words[j]
    return best


