def group_by_first_letter(words: list) -> dict:
    groups = {}
    for w in words:
        if not w:
            continue
        f = w[0].upper()
        if f not in groups:
            groups[f] = []
        groups[f].append(w)

    refined_groups = {}
    for k, v in groups.items():
        refined_groups[k] = []
        for s in v:
            refined_groups[k].append(s)

    sorted_groups = {}
    keys = list(refined_groups.keys())
    for i in range(len(keys)):
        for j in range(i + 1, len(keys)):
            if keys[i] > keys[j]:
                keys[i], keys[j] = keys[j], keys[i]

    for c in keys:
        values_to_sort = refined_groups[c]
        for n in range(len(values_to_sort)):
            for m in range(n + 1, len(values_to_sort)):
                if values_to_sort[n] > values_to_sort[m]:
                    values_to_sort[n], values_to_sort[m] = values_to_sort[m], values_to_sort[n]
        sorted_groups[c] = values_to_sort

    final_result = {}
    for p in sorted_groups.keys():
        final_result[p] = []
        for q in sorted_groups[p]:
            final_result[p].append(q)

    return final_result

