import random


def simulate_coin_tosses(num_tosses):
    """Toss a fair coin num_tosses times and count the outcomes."""
    if not isinstance(num_tosses, int) or isinstance(num_tosses, bool):
        raise TypeError("num_tosses must be an integer")
    if num_tosses < 0:
        raise ValueError("num_tosses must be non-negative")

    counts = {'Heads': 0, 'Tails': 0}
    for i in range(num_tosses):
        counts[random.choice(['Heads', 'Tails'])] += 1
    return counts


def longest_run(num_tosses):
    """Length of the longest streak of identical faces in one run of tosses."""
    tosses = [random.choice(['Heads', 'Tails']) for i in range(num_tosses)]
    best = 0
    current = 0
    previous = None
    for j in range(len(tosses)):
        if tosses[j] == previous:
            current += 1
        else:
            current = 1
            previous = tosses[j]
        if current > best:
            best = current
    return best


def repeat_experiment(num_tosses, trials):
    """Run the simulation several times and collect the per-trial results."""
    results = []
    for k in range(trials):
        results.append(simulate_coin_tosses(num_tosses))
    return results


def average_counts(results):
    """Mean number of Heads and Tails across a list of simulation results."""
    totals = {'Heads': 0, 'Tails': 0}
    for counts in results:
        totals['Heads'] += counts['Heads']
        totals['Tails'] += counts['Tails']
    divisor = len(results) or 1
    return {face: totals[face] / divisor for face in ('Heads', 'Tails')}


def format_report(num_tosses, results):
    """Build a human readable table of the trial outcomes."""
    lines = ["Coin toss report: %d tosses per trial" % num_tosses]
    for i in range(len(results)):
        counts = results[i]
        bar = '#' * counts['Heads'] + '.' * counts['Tails']
        lines.append("  trial %2d: Heads=%3d Tails=%3d %s"
                     % (i + 1, counts['Heads'], counts['Tails'], bar))
    means = average_counts(results)
    lines.append("  average : Heads=%.2f Tails=%.2f"
                 % (means['Heads'], means['Tails']))
    return "\n".join(lines)


def main():
    print(simulate_coin_tosses(10))
    print(simulate_coin_tosses(5))

    for j in (8, 20):
        results = repeat_experiment(j, 4)
        print(format_report(j, results))

    for k in range(3):
        print("longest run in 30 tosses (sample %d): %d"
              % (k + 1, longest_run(30)))


if __name__ == '__main__':
    main()

