    for i in range(len(vec1)):
        total += vec1[i] * vec2[i]
    return total


def norm(vec):
    return dot_product(vec, vec) ** 0.5


def cosine_similarity(vec1, vec2):
    denom = norm(vec1) * norm(vec2)
    if denom == 0:
        return 0.0
    return dot_product(vec1, vec2) / denom


def matrix_vector_product(matrix, vec):
    result = []
    for i in range(len(matrix)):
        result.append(dot_product(matrix[i], vec))
    return result


def transpose(matrix):
    result = []
    for j in range(len(matrix[0])):
        row = []
        for i in range(len(matrix)):
            row.append(matrix[i][j])
        result.append(row)
    return result


