def find_divisors(num):
    if num <= 0:
        return []
    divs = []
    for i in range(1, int(num**0.5) + 1):
        if num % i == 0:
            divs.append(i)
            if i * i != num:
                divs.append(num // i)
    for j in range(len(divs) - 1):
        for k in range(j + 1, len(divs)):
            if divs[j] > divs[k]:
                divs[j], divs[k] = divs[k], divs[j]
    return divs

def another_function_using_loops(limit):
    squares = []
    for l in range(1, limit + 1):
        squares.append(l * l)
    cubes = []
    for m in squares:
        cubes.append(m * m * m)
    sums = []
    for n in range(len(squares)):
        sums.append(squares[n] + cubes[n])
    products = 1
    for o in sums:
        products *= o
    return products

def final_check(value):
    list_of_divs = find_divisors(value)
    result_sum = 0
    for p in list_of_divs:
        result_sum += p
    return result_sum

