def validate_matrix(matrix):
    """Check that matrix is a rectangular list of lists of ints."""
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    width = None
    for i in range(len(matrix)):
        row = matrix[i]
        if not isinstance(row, list):
            raise TypeError("row %d is not a list" % i)
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (i, len(row), width))
        for j in range(len(row)):
            if not isinstance(row[j], int) or isinstance(row[j], bool):
                raise TypeError("element (%d, %d) is not an int" % (i, j))
    return width if width is not None else 0


def count_negative_matrix(matrix):
    """Return the number of negative numbers in a 2D list."""
    validate_matrix(matrix)
    total = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            if matrix[i][j] < 0:
                total += 1
    return total


def negatives_per_row(matrix):
    """Return a list with the count of negatives for each row."""
    counts = []
    for i in range(len(matrix)):
        count = 0
        for j in range(len(matrix[i])):
            if matrix[i][j] < 0:
                count += 1
        counts.append(count)
    return counts


def negatives_per_column(matrix):
    """Return a list with the count of negatives for each column."""
    width = validate_matrix(matrix)
    counts = [0] * width
    for k in range(width):
        for i in range(len(matrix)):
            if matrix[i][k] < 0:
                counts[k] += 1
    return counts


def format_report(matrix):
    """Build a human readable summary of the negative numbers in matrix."""
    row_counts = negatives_per_row(matrix)
    col_counts = negatives_per_column(matrix)
    lines = ["total negatives: %d" % count_negative_matrix(matrix)]
    for i in range(len(row_counts)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append("%4d" % matrix[i][j])
        lines.append("row %d: %s -> %d" % (i, " ".join(cells), row_counts[i]))
    for k in range(len(col_counts)):
        lines.append("col %d: %d" % (k, col_counts[k]))
    return "\n".join(lines)


def main():
    samples = [
        [[1, -2, 3], [-4, 5, -6]],
        [[1, 2], [3, 4]],
        [[-1, -1, -1], [0, 7, -8], [9, -3, 2]],
    ]
    for i in range(len(samples)):
        print("matrix %d" % i)
        print(format_report(samples[i]))
        print()


if __name__ == "__main__":
    main()

