def list_union(list1, list2):
    """Return the union of two lists, keeping each element only once."""
    seen = set()
    result = []
    for i in list1:
        if i not in seen:
            seen.add(i)
            result.append(i)
    for j in list2:
        if j not in seen:
            seen.add(j)
            result.append(j)
    return result


def list_intersection(list1, list2):
    """Return the elements that occur in both lists, without duplicates."""
    other = set(list2)
    seen = set()
    result = []
    for i in list1:
        if i in other and i not in seen:
            seen.add(i)
            result.append(i)
    return result


def list_difference(list1, list2):
    """Return the elements of list1 that do not occur in list2."""
    other = set(list2)
    seen = set()
    result = []
    for i in list1:
        if i not in other and i not in seen:
            seen.add(i)
            result.append(i)
    return result


def union_all(lists):
    """Fold list_union over a sequence of lists."""
    result = []
    for k in lists:
        result = list_union(result, k)
    return result


def jaccard_similarity(list1, list2):
    """Size of the intersection divided by the size of the union."""
    union = list_union(list1, list2)
    if not union:
        return 1.0
    return len(list_intersection(list1, list2)) / len(union)


def format_set(values):
    """Render a list of elements as a set-like string."""
    parts = []
    for k in values:
        parts.append(repr(k))
    return "{" + ", ".join(parts) + "}"


def main():
    pairs = [
        ([1, 2, 3], [3, 4, 5]),
        (['a', 'b'], ['c', 'd']),
        ([1, 1, 2, 2], [2, 3, 3]),
        ([], ['x', 'y']),
    ]
    for position, (left, right) in enumerate(pairs, start=1):
        print("pair %d: %s | %s" % (position, format_set(left), format_set(right)))
        print("  union        = %s" % format_set(list_union(left, right)))
        print("  intersection = %s" % format_set(list_intersection(left, right)))
        print("  left only    = %s" % format_set(list_difference(left, right)))
        print("  similarity   = %.3f" % jaccard_similarity(left, right))

    flattened = []
    for left, right in pairs:
        flattened.append(left)
        flattened.append(right)
    print("union of everything = %s" % format_set(union_all(flattened)))


if __name__ == "__main__":
    main()

