PASSPORT_LENGTH = 9


def _is_ascii_alnum(ch):
    return ("0" <= ch <= "9") or ("A" <= ch <= "Z") or ("a" <= ch <= "z")


def is_valid_passport_number(passport_num, length=PASSPORT_LENGTH):
    """Return True if passport_num is an ASCII alphanumeric string of `length`."""
    if not isinstance(passport_num, str):
        return False
    if len(passport_num) != length:
        return False
    for i in range(length):
        if not _is_ascii_alnum(passport_num[i]):
            return False
    return True


def explain(passport_num, length=PASSPORT_LENGTH):
    """Return a list of human readable reasons why passport_num is rejected."""
    if not isinstance(passport_num, str):
        return ["value is not a string"]
    reasons = []
    if len(passport_num) != length:
        reasons.append("length is %d, expected %d" % (len(passport_num), length))
    bad = []
    for j in range(len(passport_num)):
        if not _is_ascii_alnum(passport_num[j]):
            bad.append("%r at position %d" % (passport_num[j], j))
    if bad:
        reasons.append("non-alphanumeric character(s): " + ", ".join(bad))
    return reasons


def validate_batch(numbers, length=PASSPORT_LENGTH):
    """Validate a sequence of candidates, returning (value, ok, reasons) rows."""
    rows = []
    for k in range(len(numbers)):
        candidate = numbers[k]
        ok = is_valid_passport_number(candidate, length)
        rows.append((candidate, ok, [] if ok else explain(candidate, length)))
    return rows


def format_report(rows):
    """Turn validation rows into a numbered, aligned multi-line report."""
    width = 0
    for n in range(len(rows)):
        width = max(width, len(repr(rows[n][0])))
    lines = []
    for i in range(len(rows)):
        value, ok, reasons = rows[i]
        status = "VALID  " if ok else "INVALID"
        line = "%2d. %-*s %s" % (i + 1, width, repr(value), status)
        if reasons:
            line += " -- " + "; ".join(reasons)
        lines.append(line)
    separator = chr(10)
    return separator.join(lines)


def count_valid(rows):
    """Count how many validation rows passed."""
    total = 0
    for j in range(len(rows)):
        if rows[j][1]:
            total += 1
    return total


def main():
    samples = ["ABC123456", "ABC12345", "abc123456", "AB-123456",
               "123456789", "", "ÄBC123456", 123456789]
    rows = validate_batch(samples)
    print(format_report(rows))
    print("%d of %d candidates are valid." % (count_valid(rows), len(rows)))


if __name__ == "__main__":
    main()

