def dedupe(items):
    """Return the items with duplicates removed, keeping first-seen order."""
    unique = []
    for i in items:
        if i not in unique:
            unique.append(i)
    return unique


def common_in_two(first, second):
    """Return the distinct values that appear in both sequences."""
    shared = []
    for i in dedupe(first):
        for j in second:
            if i == j:
                shared.append(i)
                break
    return shared


def common_in_three_lists(list1, list2, list3):
    """Return the distinct values present in all three lists."""
    return common_in_two(common_in_two(list1, list2), list3)


def count_occurrences(value, items):
    """Return how many times value occurs in items."""
    total = 0
    for k in items:
        if k == value:
            total += 1
    return total


def occurrence_rows(shared, lists):
    """Pair every shared value with its per-list occurrence counts."""
    rows = []
    for i in shared:
        counts = []
        for j in lists:
            counts.append(count_occurrences(i, j))
        rows.append((i, counts))
    return rows


def format_report(label, lists):
    """Build a multi-line description of the common values of three lists."""
    shared = common_in_three_lists(*lists)
    lines = ["%s: %r" % (label, shared)]
    if not shared:
        lines.append("  no value occurs in all three lists")
    for value, counts in occurrence_rows(shared, lists):
        parts = []
        for i, count in enumerate(counts):
            parts.append("list%d=%d" % (i + 1, count))
        lines.append("  %r -> %s" % (value, ", ".join(parts)))
    return "\n".join(lines)


def main():
    cases = [
        ([1, 2, 3], [2, 3, 4], [3, 4, 5]),
        (['a', 'b'], ['b', 'c'], ['c', 'd']),
        ([1, 1, 2, 5, 7], [2, 2, 5, 9], [5, 5, 2, 11]),
    ]
    for i, case in enumerate(cases):
        print(format_report("case %d" % (i + 1), case))


if __name__ == "__main__":
    main()

