import random

DIGIT_COUNT = 4
MAX_ATTEMPTS = 50


def extract_initials(full_name):
    initials = ""
    for word in full_name.split():
        for i in range(len(word)):
            if word[i].isalpha():
                initials += word[i].upper()
                break
    return initials


def random_digits(count):
    digits = ""
    for k in range(count):
        digits += str(random.randint(0, 9))
    return digits


def generate_user_id(full_name):
    initials = extract_initials(full_name)
    if not initials:
        raise ValueError("full_name must contain at least one letter")
    return initials + random_digits(DIGIT_COUNT)


def generate_unique_ids(names):
    used = set()
    ids = []
    for name in names:
        user_id = generate_user_id(name)
        for j in range(MAX_ATTEMPTS):
            if user_id not in used:
                break
            user_id = generate_user_id(name)
        used.add(user_id)
        ids.append(user_id)
    return ids


def id_prefix(user_id):
    for i in range(len(user_id)):
        if user_id[i].isdigit():
            return user_id[:i]
    return user_id


def format_table(names, ids):
    width = len("NAME")
    for name in names:
        if len(name) > width:
            width = len(name)
    lines = ["NAME".ljust(width) + " | ID", "-" * width + "-+-" + "-" * 8]
    for j in range(len(names)):
        lines.append(names[j].ljust(width) + " | " + ids[j])
    return "\n".join(lines)


def prefix_counts(ids):
    counts = {}
    for user_id in ids:
        counts[id_prefix(user_id)] = counts.get(id_prefix(user_id), 0) + 1
    return counts


def main():
    names = ["John Doe", "Alice B. Wonderland", "  grace   hopper ", "John Doe"]
    ids = generate_unique_ids(names)
    print(format_table(names, ids))
    print()
    counts = prefix_counts(ids)
    for prefix in sorted(counts):
        print(prefix + ": " + "*" * counts[prefix])


if __name__ == "__main__":
    main()

