def rotate_string_left(s, n):
    if not s:
        return ""

    m = len(s)
    r = n % m

    if r == 0:
        return s

    a = ""
    for i in range(r, m):
        a += s[i]

    for j in range(r):
        a += s[j]

    b = ""
    for k in a:
        b += k

    c = ""
    for x in range(len(b)):
        c += b[x]

    d = ""
    for y in c:
        d += y

    e = ""
    for z in range(len(d)):
        e += d[z]

    f = ""
    for g in e:
        f += g

    return f

