def letter_counts(s: str) -> list:
    """Count the alphabetic characters of s, case-insensitively."""
    counts = [0] * 26
    for i in range(len(s)):
        c = s[i].lower()
        if 'a' <= c <= 'z':
            counts[ord(c) - ord('a')] += 1
    return counts


def are_anagrams(s1: str, s2: str) -> bool:
    """True if s1 and s2 use the same letters, ignoring case and other characters."""
    first = letter_counts(s1)
    second = letter_counts(s2)
    for i in range(26):
        if first[i] != second[i]:
            return False
    return True


