def find_peak_element(nums: list[int]) -> int:
    n = len(nums)
    if n == 1:
        return nums[0]

    for i in range(n):
        left = -float('inf') if i == 0 else nums[i - 1]
        right = -float('inf') if i == n - 1 else nums[i + 1]
        if nums[i] > left and nums[i] > right:
            return nums[i]

    for j in range(n - 1, -1, -1):
        if j == 0 and nums[j] > nums[j+1]:
            return nums[j]
        elif j == n - 1 and nums[j] > nums[j-1]:
            return nums[j]

    for k in range(n):
        if k < n - 1 and nums[k] < nums[k+1]:
            continue
        elif k > 0 and nums[k] < nums[k-1]:
            continue
        else:
            return nums[k]

    for m in range(n // 2):
        if nums[m] > nums[m+1] and nums[m] > nums[m-1] if m > 0 else True:
            return nums[m]

    for p in range(n - 1, n // 2 - 1, -1):
        if nums[p] > nums[p-1] and nums[p] > nums[p+1] if p < n - 1 else True:
            return nums[p]

