def tree_depth(tree_repr: list[int | None]) -> int:
    """Number of levels needed to hold the array representation."""
    return len(tree_repr).bit_length()


def validate(tree_repr: list[int | None]) -> None:
    """Reject arrays where a node hangs under a missing parent."""
    for i in range(1, len(tree_repr)):
        if tree_repr[i] is not None and tree_repr[(i - 1) // 2] is None:
            raise ValueError(f"node at index {i} has no parent")


def tree_levels(tree_repr: list[int | None]) -> list[list[int | None]]:
    """Split the array into levels, padding each level to its full width."""
    levels = []
    for k in range(tree_depth(tree_repr)):
        start = 2 ** k - 1
        level = []
        for j in range(start, start + 2 ** k):
            level.append(tree_repr[j] if j < len(tree_repr) else None)
        levels.append(level)
    return levels


def is_symmetric_tree(tree_repr: list[int | None]) -> bool:
    """A tree stored in heap order is symmetric iff every level is a palindrome."""
    validate(tree_repr)
    for level in tree_levels(tree_repr):
        n = len(level)
        for j in range(n // 2):
            if level[j] != level[n - 1 - j]:
                return False
    return True


def count_nodes(tree_repr: list[int | None]) -> int:
    total = 0
    for i in range(len(tree_repr)):
        if tree_repr[i] is not None:
            total += 1
    return total


def render(tree_repr: list[int | None]) -> str:
    """Draw the tree level by level, centred, with '.' for missing nodes."""
    levels = tree_levels(tree_repr)
    width = max((len(level) for level in levels), default=0)
    lines = []
    for level in levels:
        cells = []
        for j in range(len(level)):
            cells.append("." if level[j] is None else str(level[j]))
        lines.append(" " * (width - len(level)) + " ".join(cells))
    return "\n".join(lines)


def main() -> None:
    cases = [
        [1, 2, 2, 3, 4, 4, 3],
        [1, 2, 2, None, 3, None, 3],
        [],
        [7],
        [1, 2, 2, None, None, None, None, 5],
    ]
    for i, tree in enumerate(cases):
        print(f"case {i}: {tree}")
        try:
            answer = is_symmetric_tree(tree)
        except ValueError as exc:
            print(f"  invalid tree: {exc}")
            continue
        print(render(tree))
        print(f"  nodes = {count_nodes(tree)}, symmetric = {answer}")


if __name__ == "__main__":
    main()

