DIGITS = "0123456789"


def is_valid_us_zip(s: str) -> bool:
    """True only if s is exactly five decimal digits."""
    if not isinstance(s, str) or len(s) != 5:
        return False
    for i in range(5):
        if s[i] not in DIGITS:
            return False
    return True


def is_valid_zip_plus_four(s: str) -> bool:
    """True only if s has the form DDDDD-DDDD."""
    if not isinstance(s, str) or len(s) != 10 or s[5] != "-":
        return False
    for i in range(5):
        if s[i] not in DIGITS:
            return False
    for j in range(6, 10):
        if s[j] not in DIGITS:
            return False
    return True


def find_zip_codes(text: str) -> list:
    """Extract the 5-digit codes appearing in free text (zip+4 is truncated)."""
    found = []
    tokens = text.split()
    for k in range(len(tokens)):
        token = tokens[k].strip(".,;:()[]\"'")
        if is_valid_us_zip(token):
            found.append(token)
        elif is_valid_zip_plus_four(token):
            found.append(token[:5])
    return found


def count_by_lead_digit(zips: list) -> list:
    """Number of codes for each possible leading digit 0-9."""
    counts = [0] * 10
    for k in range(len(zips)):
        counts[int(zips[k][0])] += 1
    return counts


def format_report(zips: list) -> list:
    counts = count_by_lead_digit(zips)
    lines = []
    for i in range(10):
        if counts[i] > 0:
            lines.append("lead %d (%d): %s" % (i, counts[i], "#" * counts[i]))
    return lines


def main() -> None:
    cases = ["12345", "12345-6789", "1234", "123456", "abcde", " 1234", "00501"]
    for i in range(len(cases)):
        print("%-12r -> %s" % (cases[i], is_valid_us_zip(cases[i])))

    document = [
        "Ship to 90210, Beverly Hills.",
        "Warehouse: 10001-2345 and backup 10002.",
        "Bad entries: 1234, 123456, ABCDE.",
        "Returns go to 90277 or 94103.",
    ]
    collected = []
    for j in range(len(document)):
        collected.extend(find_zip_codes(document[j]))

    print("\nfound %d zip codes: %s" % (len(collected), ", ".join(collected)))
    report = format_report(collected)
    for k in range(len(report)):
        print(report[k])


if __name__ == "__main__":
    main()

