DAY_NAMES = ('Monday', 'Tuesday', 'Wednesday', 'Thursday',
             'Friday', 'Saturday', 'Sunday')
MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
MONTH_NAMES = ('January', 'February', 'March', 'April', 'May', 'June', 'July',
               'August', 'September', 'October', 'November', 'December')


def is_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def parse_date(text):
    parts = text.split('-')
    if len(parts) != 3:
        raise ValueError("date must be in 'YYYY-MM-DD' format: %r" % (text,))
    widths = (4, 2, 2)
    for i in range(3):
        if len(parts[i]) != widths[i] or not parts[i].isdigit():
            raise ValueError("bad date component %r in %r" % (parts[i], text))
    year, month, day = (int(parts[i]) for i in range(3))
    if year < 1:
        raise ValueError('year must be positive: %d' % year)
    if not 1 <= month <= 12:
        raise ValueError('month out of range: %d' % month)
    if not 1 <= day <= days_in_month(year, month):
        raise ValueError('day out of range for month: %d' % day)
    return year, month, day


def ordinal_day(year, month, day):
    total = 0
    for i in range(1, year):
        total += 366 if is_leap_year(i) else 365
    for j in range(1, month):
        total += days_in_month(year, j)
    return total + day


def get_day_of_week(date_string):
    year, month, day = parse_date(date_string)
    return DAY_NAMES[(ordinal_day(year, month, day) - 1) % 7]


def count_weekday_in_month(year, month, day_name):
    count = 0
    for k in range(1, days_in_month(year, month) + 1):
        if DAY_NAMES[(ordinal_day(year, month, k) - 1) % 7] == day_name:
            count += 1
    return count


def main():
    samples = ['2023-03-15', '2024-01-01', '2000-02-29', '1900-01-01']
    width = 0
    for i in range(len(samples)):
        width = max(width, len(samples[i]))
    for i in range(len(samples)):
        print('%-*s -> %s' % (width, samples[i], get_day_of_week(samples[i])))

    print('\nFridays per month in 2024:')
    for j in range(1, 13):
        print('%-10s %d' % (MONTH_NAMES[j - 1],
                            count_weekday_in_month(2024, j, 'Friday')))


if __name__ == '__main__':
