def percent_decode(text):
    """Decode %XX escapes in a single path segment."""
    chunks = text.split('%')
    decoded = [chunks[0]]
    for k in range(1, len(chunks)):
        chunk = chunks[k]
        if len(chunk) >= 2:
            try:
                decoded.append(chr(int(chunk[:2], 16)) + chunk[2:])
            except ValueError:
                decoded.append('%' + chunk)
        else:
            decoded.append('%' + chunk)
    return ''.join(decoded)


def parse_url_path_segments(path):
    """Split a URL path into its non-empty, percent-decoded segments."""
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    path = path.split('#', 1)[0].split('?', 1)[0]
    raw_parts = path.split('/')
    segments = []
    for i in range(len(raw_parts)):
        if raw_parts[i]:
            segments.append(percent_decode(raw_parts[i]))
    return segments


def normalize_segments(segments):
    """Resolve '.' and '..' segments the way a web server would."""
    stack = []
    for j in range(len(segments)):
        segment = segments[j]
        if segment == '.':
            continue
        if segment == '..':
            if stack:
                stack.pop()
            continue
        stack.append(segment)
    return stack


def match_route(pattern, segments):
    """Match segments against a pattern such as '/users/:id'; return params or None."""
    expected = parse_url_path_segments(pattern)
    if len(expected) != len(segments):
        return None
    params = {}
    for i in range(len(expected)):
        token = expected[i]
        if token.startswith(':'):
            params[token[1:]] = segments[i]
        elif token != segments[i]:
            return None
    return params


def resolve(routes, path):
    """Return (pattern, params) for the first route matching path, or (None, {})."""
    segments = normalize_segments(parse_url_path_segments(path))
    for k in range(len(routes)):
        params = match_route(routes[k], segments)
        if params is not None:
            return routes[k], params
    return None, {}


def format_report(routes, paths):
    lines = []
    for i in range(len(paths)):
        path = paths[i]
        segments = parse_url_path_segments(path)
        pattern, params = resolve(routes, path)
        target = pattern if pattern else '<no route>'
        detail = ', '.join('%s=%s' % item for item in sorted(params.items()))
        lines.append('%d. %-28s %-34s -> %s %s' % (i + 1, path, segments, target, detail))
    return lines


def main():
    routes = ['/api/v1/users', '/api/v1/users/:id', '/home', '/files/:name/raw']
    paths = [
        '/api/v1/users/123',
        '/home/',
        '/api/v1/users',
        '/api/v1/../v1/users/7?page=2',
        '/files/report%20final/raw',
        '/nope/at/all',
    ]
    lines = format_report(routes, paths)
    for j in range(len(lines)):
        print(lines[j])


if __name__ == '__main__':
    main()

