import math


def circle_circumference(radius):
    """Return the circumference of a circle with the given radius."""
    if isinstance(radius, bool) or not isinstance(radius, (int, float)):
        raise TypeError("radius must be an int or a float")
    if radius < 0:
        raise ValueError("radius must not be negative")
    return 2.0 * math.pi * float(radius)


def parse_radii(text):
    """Turn a comma or space separated string of numbers into a list of floats."""
    tokens = text.replace(",", " ").split()
    radii = []
    for i in range(len(tokens)):
        try:
            radii.append(float(tokens[i]))
        except ValueError:
            raise ValueError("entry %d (%r) is not a number" % (i + 1, tokens[i]))
    return radii


def circumference_table(radii):
    """Build an aligned, numbered text table of radii and their circumferences."""
    headers = ("#", "radius", "circumference")
    rows = []
    for i in range(len(radii)):
        rows.append(("%d" % (i + 1),
                     "%.3f" % radii[i],
                     "%.6f" % circle_circumference(radii[i])))
    widths = [len(header) for header in headers]
    for row in rows:
        for j in range(len(row)):
            widths[j] = max(widths[j], len(row[j]))
    lines = ["  ".join(headers[j].rjust(widths[j]) for j in range(len(headers))),
             "  ".join("-" * width for width in widths)]
    for row in rows:
        lines.append("  ".join(row[j].rjust(widths[j]) for j in range(len(row))))
    return "\n".join(lines)


def growth_steps(radii):
    """Circumference increase from each radius to the next one in the list."""
    steps = []
    for i in range(1, len(radii)):
        steps.append(circle_circumference(radii[i]) - circle_circumference(radii[i - 1]))
    return steps


def total_length(radii):
    """Total circumference of all the given circles."""
    return sum(circle_circumference(radius) for radius in radii)


def concentric_lengths(radius, rings):
    """Circumferences of `rings` evenly spaced circles up to `radius`."""
    if rings < 1:
        raise ValueError("rings must be at least 1")
    lengths = []
    for k in range(1, rings + 1):
        lengths.append(circle_circumference(radius * k / rings))
    return lengths


def main():
    radii = parse_radii("5, 1, 2.5, 10")
    print(circumference_table(radii))
    print()
    steps = growth_steps(radii)
    for i in range(len(steps)):
        print("step %d: %+.6f" % (i + 1, steps[i]))
    print("total: %.6f" % total_length(radii))
    print()
    rings = concentric_lengths(5, 4)
    for j in range(len(rings)):
        print("ring %d: %.6f" % (j + 1, rings[j]))


if __name__ == "__main__":
    main()

