def split_words(text):
    """Split a space separated string into its words."""
    if text == '':
        return []
    words = []
    start = 0
    for i in range(len(text)):
        if text[i] == ' ':
            words.append(text[start:i])
            start = i + 1
    words.append(text[start:])
    return words


def join_words(words):
    """Join words back together with single spaces."""
    out = ''
    for j in range(len(words)):
        if j > 0:
            out += ' '
        out += words[j]
    return out


def reverse_words(text):
    """Reverse the order of the words in text, keeping each word intact."""
    words = split_words(text)
    flipped = []
    for k in range(len(words) - 1, -1, -1):
        flipped.append(words[k])
    return join_words(flipped)


def longest_word(text):
    """Return the longest word of text (the first one, on a tie)."""
    words = split_words(text)
    best = ''
    for i in range(len(words)):
        if len(words[i]) > len(best):
            best = words[i]
    return best


