import sys


def validate_flag_names(names):
    """Check that the expected flag names are usable, returning them as a list."""
    cleaned = []
    for i in range(len(names)):
        name = names[i]
        if not isinstance(name, str):
            raise TypeError("flag name at position %d is not a string: %r" % (i, name))
        if not name or name.startswith("-"):
            raise ValueError("invalid flag name: %r" % (name,))
        cleaned.append(name)
    for i in range(len(cleaned)):
        for j in range(i + 1, len(cleaned)):
            if cleaned[i] == cleaned[j]:
                raise ValueError("duplicate flag name: %r" % (cleaned[i],))
    return cleaned


def split_args(argv):
    """Split argv into (flag names without '--', positional arguments).

    Everything following a bare '--' is treated as positional.
    """
    end = len(argv)
    for i in range(len(argv)):
        if argv[i] == "--":
            end = i
            break
    flags = []
    positionals = []
    for j in range(end):
        token = argv[j]
        if token.startswith("--") and len(token) > 2:
            flags.append(token[2:])
        else:
            positionals.append(token)
    for k in range(end + 1, len(argv)):
        positionals.append(argv[k])
    return flags, positionals


def parse_bool_flags(args, flag_names):
    """Map each expected flag name to whether it appears in args."""
    expected = validate_flag_names(flag_names)
    present = split_args(list(args))[0]
    result = {}
    for i in range(len(expected)):
        result[expected[i]] = expected[i] in present
    return result


def find_unknown_flags(args, flag_names):
    """Return the flags given on the command line that were not expected."""
    expected = validate_flag_names(flag_names)
    given = split_args(list(args))[0]
    unknown = []
    for i in range(len(given)):
        if given[i] not in expected and given[i] not in unknown:
            unknown.append(given[i])
    return unknown


def format_report(args, flag_names):
    """Build human readable lines describing how args were interpreted."""
    parsed = parse_bool_flags(args, flag_names)
    positionals = split_args(list(args))[1]
    reported = sorted(parsed)
    lines = ["command line: " + " ".join(args)]
    for i in range(len(reported)):
        lines.append("  %d. --%s = %s" % (i + 1, reported[i], parsed[reported[i]]))
    for j in range(len(positionals)):
        lines.append("  positional[%d]: %s" % (j, positionals[j]))
    unknown = find_unknown_flags(args, flag_names)
    for k in range(len(unknown)):
        lines.append("  warning: unknown flag --%s" % unknown[k])
    return lines


def main(argv=None):
    argv = list(sys.argv[1:]) if argv is None else list(argv)
    for line in format_report(argv, ["verbose", "debug", "quiet", "help"]):
        print(line)


if __name__ == "__main__":
    main()

