import sys


def validate_html(html):
    """Check that every '<' has a matching '>' and that no brackets nest."""
    if not isinstance(html, str):
        raise TypeError("expected a string of HTML content")
    open_at = -1
    for i in range(len(html)):
        c = html[i]
        if c == '<':
            if open_at >= 0:
                raise ValueError("nested '<' at position %d" % i)
            open_at = i
        elif c == '>':
            if open_at < 0:
                raise ValueError("unmatched '>' at position %d" % i)
            open_at = -1
    if open_at >= 0:
        raise ValueError("unclosed tag starting at position %d" % open_at)


def remove_html_tags(html):
    """Return the plain text of html, with all well-formed tags removed."""
    validate_html(html)
    pieces = []
    inside = False
    for i in range(len(html)):
        c = html[i]
        if c == '<':
            inside = True
        elif c == '>':
            inside = False
        elif not inside:
            pieces.append(c)
    return ''.join(pieces)


def find_raw_tags(html):
    """Return the text found between each '<' and '>' pair, in order."""
    validate_html(html)
    raw = []
    start = -1
    for i in range(len(html)):
        c = html[i]
        if c == '<':
            start = i
        elif c == '>':
            raw.append(html[start + 1:i])
    return raw


def tag_name(raw):
    """Normalise a raw tag body such as '/p' or 'a href="x"' to its name."""
    body = raw.strip().lstrip('/').rstrip('/')
    name = []
    for i in range(len(body)):
        if body[i].isspace():
            break
        name.append(body[i])
    return ''.join(name).lower()


def count_tag_names(html):
    """Map each tag name appearing in html to how often it occurs."""
    tags = find_raw_tags(html)
    counts = {}
    for i in range(len(tags)):
        name = tag_name(tags[i])
        if name:
            counts[name] = counts.get(name, 0) + 1
    return counts


def describe(html):
    """Return the stripped text and a summary of the tags that were removed."""
    text = remove_html_tags(html)
    counts = count_tag_names(html)
    names = sorted(counts)
    parts = []
    for i in range(len(names)):
        parts.append("%s x%d" % (names[i], counts[names[i]]))
    return text, ', '.join(parts) if parts else 'no tags'


def main(argv):
    samples = argv[1:] or ['<h1>Title</h1><p>Content</p>',
                           '<div>Hello <b>world</b>!</div>']
    for i in range(len(samples)):
        try:
            text, summary = describe(samples[i])
        except (TypeError, ValueError) as err:
            print("%d. error: %s" % (i + 1, err))
            continue
        print("%d. text=%r  tags: %s" % (i + 1, text, summary))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

