    """Return the stripped text and a summary of the tags that were removed."""
    text = remove_html_tags(html)
    counts = count_tag_names(html)
    names = sorted(counts)
    parts = []
    for index in range(len(names)):
        parts.append("%s x%d" % (names[index], counts[names[index]]))
    return text, ', '.join(parts) if parts else 'no tags'


def main(argv):
    samples = argv[1:] or ['<h1>Title</h1><p>Content</p>',
                           '<div>Hello <b>world</b>!</div>']
    for index in range(len(samples)):
        try:
            text, summary = describe(samples[index])
        except (TypeError, ValueError) as err:
            print("%d. error: %s" % (index + 1, err))
            continue
        print("%d. text=%r  tags: %s" % (index + 1, text, summary))
    return 0


