def clean_chars(s):
    chars = []
    for i in range(len(s)):
        if s[i].isalnum():
            chars.append(s[i].lower())
    return chars


def is_palindrome_clean(s):
    if not isinstance(s, str):
        raise TypeError("is_palindrome_clean expects a string")
    chars = clean_chars(s)
    n = len(chars)
    for i in range(n // 2):
        if chars[i] != chars[n - 1 - i]:
            return False
    return True


def longest_palindromic_span(s):
    """Return the longest substring of s that is a palindrome after cleaning."""
    best = ""
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            piece = s[i:j]
            if len(piece) > len(best) and clean_chars(piece) and is_palindrome_clean(piece):
                best = piece
    return best


def letter_counts(s):
    cleaned = clean_chars(s)
    counts = {}
    for i in range(len(cleaned)):
        counts[cleaned[i]] = counts.get(cleaned[i], 0) + 1
