def _trim(s):
    start, end = len(s), 0
    for i in range(len(s)):
        if not s[i].isspace():
            start = i
            break
    for j in range(len(s) - 1, start - 1, -1):
        if not s[j].isspace():
            end = j + 1
            break
    return s[start:end]


def _count_digits(s, start):
    """Number of consecutive decimal digits in s starting at index start."""
    total = 0
    for i in range(start, len(s)):
        if not ('0' <= s[i] <= '9'):
            break
        total += 1
    return total


def _classify(t):
    """Return 'integer', 'float', or None for the already trimmed text t."""
    end = len(t)
    pos = 1 if t[:1] in ('+', '-') else 0
    whole = _count_digits(t, pos)
    pos += whole
    kind = 'integer'
    if t[pos:pos + 1] == '.':
        kind = 'float'
        pos += 1
        frac = _count_digits(t, pos)
        pos += frac
        if whole == 0 and frac == 0:
            return None
    elif whole == 0:
        return None
    if t[pos:pos + 1] in ('e', 'E'):
        kind = 'float'
        pos += 1
        if t[pos:pos + 1] in ('+', '-'):
            pos += 1
        expo = _count_digits(t, pos)
        pos += expo
        if expo == 0:
            return None
    return kind if pos == end else None


def format_report(samples):
    """Build aligned report lines: index, input, validity, detected kind."""
    width = 0
    for i in range(len(samples)):
        width = max(width, len(repr(samples[i])))
    lines = []
    for j in range(len(samples)):
        kind = _classify(_trim(samples[j])) or 'invalid'
        lines.append('%2d  %-*s  %-5s  %s' % (j + 1, width, repr(samples[j]),
                                              is_valid_number(samples[j]), kind))
    return lines


def is_valid_number(s):
    """True if s represents a valid integer or floating-point number."""
    if not isinstance(s, str):
        return False
    return _classify(_trim(s)) is not None


def main():
    samples = ['123', '3.14', 'abc', '  -42  ', '+.5', '.', '1e10', '2E-3',
               '1e', '0.0.1', '007', '-0.0']
    for line in format_report(samples):
        print(line)
    valid = sum(1 for sample in samples if is_valid_number(sample))
    print('%d of %d inputs are valid numbers' % (valid, len(samples)))


if __name__ == '__main__':
    main()

