def validate_input(nums):
    """Return the input as a list, raising TypeError on non-integer entries."""
    if not isinstance(nums, (list, tuple)):
        raise TypeError("expected a list of integers")
    values = list(nums)
    for i in range(len(values)):
        if isinstance(values[i], bool) or not isinstance(values[i], int):
            raise TypeError("element at index %d is not an integer: %r" % (i, values[i]))
    return values


def count_occurrences(nums):
    """Map every value in nums to the number of times it appears."""
    counts = {}
    for k in nums:
        counts[k] = counts.get(k, 0) + 1
    return counts


def find_all_duplicates(nums):
    """Return every value that appears more than once in nums."""
    values = validate_input(nums)
    counts = count_occurrences(values)
    duplicates = []
    for k in counts:
        if counts[k] > 1:
            duplicates.append(k)
    return duplicates


def first_repeat_positions(nums, duplicates):
    """For each duplicate, report the index where its second copy appears."""
    positions = {}
    for j in range(len(duplicates)):
        target = duplicates[j]
        seen = 0
        for i in range(len(nums)):
            if nums[i] == target:
                seen += 1
                if seen == 2:
                    positions[target] = i
                    break
    return positions


def format_report(nums, duplicates):
    """Build a human readable summary of the duplicates found in nums."""
    counts = count_occurrences(nums)
    positions = first_repeat_positions(nums, duplicates)
    lines = ["input: %r" % (nums,)]
    if not duplicates:
        lines.append("  no duplicates")
        return "\n".join(lines)
    ordered = sorted(duplicates)
    for k in ordered:
        lines.append(
            "  value %d appears %d times, repeats first at index %d"
            % (k, counts[k], positions[k])
        )
    lines.append("  duplicates: %r" % (ordered,))
    return "\n".join(lines)


