def validate_numbers(values):
    """Return the values as floats, raising ValueError on bad entries."""
    cleaned = []
    for i in range(len(values)):
        item = values[i]
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise ValueError("element %d is not a number: %r" % (i, item))
        cleaned.append(float(item))
    return cleaned


def count_above_threshold(numbers, threshold):
    """Count how many entries of `numbers` are strictly greater than `threshold`."""
    values = validate_numbers(numbers)
    limit = float(threshold)
    total = 0
    for i in range(len(values)):
        if values[i] > limit:
            total += 1
    return total


def counts_for_thresholds(numbers, thresholds):
    """Count the entries above each threshold, preserving the threshold order."""
    results = []
    for j in range(len(thresholds)):
        results.append(count_above_threshold(numbers, thresholds[j]))
    return results


def cumulative_survivors(numbers):
    """For each value v in `numbers`, count how many entries are above v."""
    values = validate_numbers(numbers)
    survivors = []
    for i in range(len(values)):
        above = 0
        for k in range(len(values)):
            if values[k] > values[i]:
                above += 1
        survivors.append(above)
    return survivors


def format_report(numbers, thresholds):
    """Build a human readable table of threshold -> count -> fraction."""
    counts = counts_for_thresholds(numbers, thresholds)
    size = len(numbers)
    lines = ["threshold  count  fraction"]
    for i in range(len(thresholds)):
        fraction = counts[i] / size if size else 0.0
        lines.append("%9.2f  %5d  %7.2f%%" % (float(thresholds[i]), counts[i], 100.0 * fraction))
    return "\n".join(lines)


def main():
    samples = [
        ([1, 5, 2, 8, 3], 3),
        ([1, 2, 3], 5),
        ([-4.5, 0, 0.5, 12, 7, 7], 7),
    ]
    for j in range(len(samples)):
        data, threshold = samples[j]
        print("count_above_threshold(%r, %r) = %d"
              % (data, threshold, count_above_threshold(data, threshold)))

    data = [1, 5, 2, 8, 3]
    print()
    print(format_report(data, [0, 3, 5, 8]))

    print()
    survivors = cumulative_survivors(data)
    for i in range(len(data)):
        print("%d has %d larger value(s)" % (data[i], survivors[i]))


if __name__ == "__main__":
    main()

