import random

SIZE = 5


def validate_card(bingo_card):
    if len(bingo_card) != SIZE:
        raise ValueError("card must have %d rows" % SIZE)
    for i in range(SIZE):
        row = bingo_card[i]
        if len(row) != SIZE:
            raise ValueError("row %d must have %d cells" % (i, SIZE))
        for j in range(SIZE):
            if not isinstance(row[j], bool):
                raise ValueError("cell (%d, %d) is not a boolean" % (i, j))


def check_diagonal_bingo(bingo_card):
    validate_card(bingo_card)
    main = True
    anti = True
    for i in range(SIZE):
        if not bingo_card[i][i]:
            main = False
        if not bingo_card[i][SIZE - 1 - i]:
            anti = False
    return main or anti


def diagonal_progress(bingo_card):
    validate_card(bingo_card)
    main = 0
    anti = 0
    for i in range(SIZE):
        if bingo_card[i][i]:
            main += 1
        if bingo_card[i][SIZE - 1 - i]:
            anti += 1
    return main, anti


def random_card(marks, rng):
    positions = []
    for i in range(SIZE):
        for j in range(SIZE):
            positions.append((i, j))
    rng.shuffle(positions)
    card = [[False] * SIZE for _ in range(SIZE)]
    for k in range(marks):
        i, j = positions[k]
        card[i][j] = True
    return card


def format_card(bingo_card):
    lines = []
    for i in range(SIZE):
        cells = []
