def validate_board(board):
    if len(board) != 3:
        raise ValueError("board must have exactly 3 rows")
    for i in range(3):
        row = board[i]
        if len(row) != 3:
            raise ValueError("row %d must have exactly 3 cells" % i)
        for j in range(3):
            if row[j] not in ('X', 'O', ' '):
                raise ValueError("bad cell at (%d, %d): %r" % (i, j, row[j]))


def validate_player(player):
    if player not in ('X', 'O'):
        raise ValueError("player must be 'X' or 'O', got %r" % (player,))


def check_tic_tac_toe_win_rc(board, player):
    validate_board(board)
    validate_player(player)
    for i in range(3):
        full = True
        for j in range(3):
            if board[i][j] != player:
                full = False
        if full:
            return True
    for j in range(3):
        full = True
        for i in range(3):
            if board[i][j] != player:
                full = False
        if full:
            return True
    return False


def winning_lines(board, player):
    lines = []
    for i in range(3):
        if all(board[i][j] == player for j in range(3)):
            lines.append("row %d" % (i + 1))
    for j in range(3):
        if all(board[i][j] == player for i in range(3)):
            lines.append("column %d" % (j + 1))
    return lines


def format_board(board):
    parts = []
    for i in range(3):
        parts.append(" " + " | ".join(board[i][j] for j in range(3)))
        if i < 2:
            parts.append("---+---+---")
    return "\n".join(parts)


def report(board, players=('X', 'O')):
    lines = [format_board(board)]
    for player in players:
        won = check_tic_tac_toe_win_rc(board, player)
        detail = ", ".join(winning_lines(board, player)) if won else "no line"
        lines.append("%s wins: %s (%s)" % (player, won, detail))
    return "\n".join(lines)


def main():
