    for index in range(len(pin)):
        if pin[index] not in "0123456789":
            return False
    return True


def digit_frequency(pins):
    counter = Counter()
    for index in range(len(pins)):
        for column in range(4):
            counter[pins[index][column]] += 1
    return counter


def has_repeated_digit(pin):
    for index in range(len(pin)):
